fn reg_bug_0227_lrm_violation() {
    let src = "/* Copyright 2018 ETH Zurich and University of Bologna.\n * Copyright and related rights are licensed under the Solderpad Hardware\n * License, Version 0.51 (the “License”); you may not use this file except in\n * compliance with the License.  You may obtain a copy of the License at\n * http://solderpad.org/licenses/SHL-0.51. Unless required by applicable law\n * or agreed to in writing, software, hardware and materials distributed under\n * this License is distributed on an “AS IS” BASIS, WITHOUT WARRANTIES OR\n * CONDITIONS OF ANY KIND, either express or implied. See the License for the\n * specific language governing permissions and limitations under the License.\n *\n * File:   ariane_pkg.sv\n * Author: Florian Zaruba <zarubaf@iis.ee.ethz.ch>\n * Date:   8.4.2017\n *\n * Description: Contains all the necessary defines for Ariane\n *              in one package.\n */\n\n// this is needed to propagate the\n// configuration in case Ariane is\n// instantiated in OpenPiton\n`ifdef PITON_ARIANE\n`include \"l15.tmp.h\"\n`endif\n\n/// This package contains `functions` and global defines for CVA6.\n/// *Note*: There are some parameters here as well which will eventually be\n/// moved out to favour a fully parameterizable core.\npackage ariane_pkg;\n\n  // TODO: Slowly move those parameters to the new system.\n  localparam BITS_SATURATION_COUNTER = 2;\n\n  // depth of store-buffers, this needs to be a power of two\n  localparam logic [2:0] DEPTH_SPEC = 'd4;\n\n  // if CVA6Cfg.DCacheType = cva6_config_pkg::WT\n  // we can use a small commit queue since we have a write buffer in the dcache\n  // we could in principle do without the commit queue in this case, but the timing degrades if we do that due\n  // to longer paths into the commit stage\n  // if CVA6Cfg.DCacheType = cva6_config_pkg::WB\n  // allocate more space for the commit buffer to be on the safe side, this needs to be a power of two\n  localparam logic [2:0] DEPTH_COMMIT = 'd4;\n\n  // Transprecision float unit\n  localparam int unsigned LAT_COMP_FP32 = 'd2;\n  localparam int unsigned LAT_COMP_FP64 = 'd3;\n  localparam int unsigned LAT_COMP_FP16 = 'd1;\n  localparam int unsigned LAT_COMP_FP16ALT = 'd1;\n  localparam int unsigned LAT_COMP_FP8 = 'd1;\n  localparam int unsigned LAT_DIVSQRT = 'd2;\n  localparam int unsigned LAT_NONCOMP = 'd1;\n  localparam int unsigned LAT_CONV = 'd2;\n\n  localparam logic [31:0] OPENHWGROUP_MVENDORID = 32'h0602;\n  localparam logic [31:0] ARIANE_MARCHID = 32'd3;\n  localparam logic [31:0] ARIANE_MIMPID = 32'd0;\n\n  // 32 registers\n  localparam REG_ADDR_SIZE = 5;\n\n  // Read ports for general purpose register files\n  localparam NR_RGPR_PORTS = 2;\n\n  // static debug hartinfo\n  // debug causes\n  localparam logic [2:0] CauseBreakpoint = 3'h1;\n  localparam logic [2:0] CauseTrigger = 3'h2;\n  localparam logic [2:0] CauseRequest = 3'h3;\n  localparam logic [2:0] CauseSingleStep = 3'h4;\n  // amount of data count registers implemented\n  localparam logic [3:0] DataCount = 4'h2;\n\n  // address where data0-15 is shadowed or if shadowed in a CSR\n  // address of the first CSR used for shadowing the data\n  localparam logic [11:0] DataAddr = 12'h380;  // we are aligned with Rocket here\n  typedef struct packed {\n    logic [31:24] zero1;\n    logic [23:20] nscratch;\n    logic [19:17] zero0;\n    logic         dataaccess;\n    logic [15:12] datasize;\n    logic [11:0]  dataaddr;\n  } hartinfo_t;\n\n  localparam hartinfo_t DebugHartInfo = '{\n      zero1: '0,\n      nscratch: 2,  // Debug module needs at least two scratch regs\n      zero0: '0,\n      dataaccess: 1'b1,  // data registers are memory mapped in the debugger\n      datasize: DataCount,\n      dataaddr: DataAddr\n  };\n\n  // enables a commit log which matches spikes commit log format for easier trace comparison\n  localparam bit ENABLE_SPIKE_COMMIT_LOG = 1'b1;\n\n  // ------------- Dangerous -------------\n  // if set to zero a flush will not invalidate the cache-lines, in a single core environment\n  // where coherence is not necessary this can improve performance. This needs to be switched on\n  // when more than one core is in a system\n  localparam logic INVALIDATE_ON_FLUSH = 1'b1;\n\n`ifdef SPIKE_TANDEM\n  // Spike still places 0 in TVAL for ENV_CALL_* exceptions.\n  // This may eventually go away when Spike starts to handle TVAL for *all* exceptions.\n  localparam bit ZERO_TVAL = 1'b1;\n`else\n  localparam bit ZERO_TVAL = 1'b0;\n`endif\n\n  // read mask for SSTATUS over MSTATUS\n  function automatic logic [63:0] smode_status_read_mask(config_pkg::cva6_cfg_t Cfg);\n    return riscv::SSTATUS_UIE\n    | riscv::SSTATUS_SIE\n    | riscv::SSTATUS_SPIE\n    | riscv::SSTATUS_UBE\n    | riscv::SSTATUS_SPP\n    | riscv::SSTATUS_FS\n    | riscv::SSTATUS_XS\n    | riscv::SSTATUS_SUM\n    | riscv::SSTATUS_MXR\n    | riscv::SSTATUS_UPIE\n    | riscv::SSTATUS_SPIE\n    | riscv::SSTATUS_UXL\n    | riscv::sstatus_sd(Cfg.IS_XLEN64);\n  endfunction\n\n  localparam logic [63:0] SMODE_STATUS_WRITE_MASK = riscv::SSTATUS_SIE\n                                                    | riscv::SSTATUS_SPIE\n                                                    | riscv::SSTATUS_SPP\n                                                    | riscv::SSTATUS_FS\n                                                    | riscv::SSTATUS_SUM\n                                                    | riscv::SSTATUS_MXR;\n\n  localparam logic [63:0] HSTATUS_WRITE_MASK      = riscv::HSTATUS_VSBE\n                                                    | riscv::HSTATUS_GVA\n                                                    | riscv::HSTATUS_SPV\n                                                    | riscv::HSTATUS_SPVP\n                                                    | riscv::HSTATUS_HU\n                                                    | riscv::HSTATUS_VTVM\n                                                    | riscv::HSTATUS_VTW\n                                                    | riscv::HSTATUS_VTSR;\n\n  // hypervisor delegable interrupts\n  function automatic logic [31:0] hs_deleg_interrupts(config_pkg::cva6_cfg_t Cfg);\n    return riscv::MIP_VSSIP | riscv::MIP_VSTIP | riscv::MIP_VSEIP;\n  endfunction\n\n  // virtual supervisor delegable interrupts\n  function automatic logic [31:0] vs_deleg_interrupts(config_pkg::cva6_cfg_t Cfg);\n    return riscv::MIP_VSSIP | riscv::MIP_VSTIP | riscv::MIP_VSEIP;\n  endfunction\n\n  // ---------------\n  // AXI\n  // ---------------\n\n  typedef enum logic {\n    SINGLE_REQ,\n    CACHE_LINE_REQ\n  } ad_req_t;\n\n  // ---------------\n  // Fetch Stage\n  // ---------------\n\n  // leave as is (fails with >8 entries and wider fetch width)\n  localparam int unsigned FETCH_FIFO_DEPTH = 4;\n  localparam int unsigned FETCH_ADDR_FIFO_DEPTH = 2;\n\n  typedef enum logic [2:0] {\n    NoCF,    // No control flow prediction\n    Branch,  // Branch\n    Jump,    // Jump to address from immediate\n    JumpR,   // Jump to address from registers\n    Return   // Return Address Prediction\n  } cf_t;\n\n  typedef struct packed {\n    logic valid;\n    logic taken;\n  } bht_prediction_t;\n\n  typedef struct packed {\n    logic       valid;\n    logic [1:0] saturation_counter;\n  } bht_t;\n\n  typedef enum logic [3:0] {\n    NONE,       // 0\n    LOAD,       // 1\n    STORE,      // 2\n    ALU,        // 3\n    CTRL_FLOW,  // 4\n    MULT,       // 5\n    CSR,        // 6\n    FPU,        // 7\n    FPU_VEC,    // 8\n    CVXIF,      // 9\n    ACCEL,      // 10\n    AES         // 11\n  } fu_t;\n\n  // Index of writeback ports\n  localparam FLU_WB = 0;\n  localparam STORE_WB = 1;\n  localparam LOAD_WB = 2;\n  localparam FPU_WB = 3;\n  localparam ACC_WB = 4;\n  localparam X_WB = 4;\n\n  localparam EXC_OFF_RST = 8'h80;\n\n  localparam SupervisorIrq = 1;\n  localparam MachineIrq = 0;\n\n  // ---------------\n  // Cache config\n  // ---------------\n\n  // for usage in OpenPiton we have to propagate the openpiton L15 configuration from l15.h\n`ifdef PITON_ARIANE\n\n`ifndef CONFIG_L1I_CACHELINE_WIDTH\n  `define CONFIG_L1I_CACHELINE_WIDTH 128\n`endif\n\n`ifndef CONFIG_L1I_ASSOCIATIVITY\n  `define CONFIG_L1I_ASSOCIATIVITY 4\n`endif\n\n`ifndef CONFIG_L1I_SIZE\n  `define CONFIG_L1I_SIZE 16*1024\n`endif\n\n`ifndef CONFIG_L1D_CACHELINE_WIDTH\n  `define CONFIG_L1D_CACHELINE_WIDTH 128\n`endif\n\n`ifndef CONFIG_L1D_ASSOCIATIVITY\n  `define CONFIG_L1D_ASSOCIATIVITY 8\n`endif\n\n`ifndef CONFIG_L1D_SIZE\n  `define CONFIG_L1D_SIZE 32*1024\n`endif\n\n`ifndef L15_THREADID_WIDTH\n  `define L15_THREADID_WIDTH 3\n`endif\n\n  // I$\n  localparam int unsigned ICACHE_LINE_WIDTH = `CONFIG_L1I_CACHELINE_WIDTH;\n  localparam int unsigned ICACHE_SET_ASSOC = `CONFIG_L1I_ASSOCIATIVITY;\n  localparam int unsigned ICACHE_INDEX_WIDTH = $clog2(`CONFIG_L1I_SIZE / ICACHE_SET_ASSOC);\n  localparam int unsigned ICACHE_TAG_WIDTH = riscv::PLEN - ICACHE_INDEX_WIDTH;\n  localparam int unsigned AXI_USER_WIDTH = 64;\n  localparam int unsigned ICACHE_USER_LINE_WIDTH = (AXI_USER_WIDTH == 1) ? 4 : 128;  // in bit\n  // D$\n  localparam int unsigned DCACHE_LINE_WIDTH = `CONFIG_L1D_CACHELINE_WIDTH;\n  localparam int unsigned DCACHE_SET_ASSOC = `CONFIG_L1D_ASSOCIATIVITY;\n  localparam int unsigned DCACHE_INDEX_WIDTH = $clog2(`CONFIG_L1D_SIZE / DCACHE_SET_ASSOC);\n  localparam int unsigned DCACHE_TAG_WIDTH = riscv::PLEN - DCACHE_INDEX_WIDTH;\n  localparam int unsigned DCACHE_USER_LINE_WIDTH = (AXI_USER_WIDTH == 1) ? 4 : 128;  // in bit\n  localparam int unsigned DCACHE_USER_WIDTH = cva6_config_pkg::CVA6ConfigDataUserWidth;\n\n  localparam int unsigned MEM_TID_WIDTH = `L15_THREADID_WIDTH;\n`endif\n\n  // ---------------\n  // EX Stage\n  // ---------------\n\n  typedef enum logic [7:0] {  // basic ALU op\n    ADD,\n    SUB,\n    ADDW,\n    SUBW,\n    // logic operations\n    XORL,\n    ORL,\n    ANDL,\n    // shifts\n    SRA,\n    SRL,\n    SLL,\n    SRLW,\n    SLLW,\n    SRAW,\n    // comparisons\n    LTS,\n    LTU,\n    GES,\n    GEU,\n    EQ,\n    NE,\n    // jumps\n    JALR,\n    BRANCH,\n    // set lower than operations\n    SLTS,\n    SLTU,\n    // CSR functions\n    MRET,\n    SRET,\n    DRET,\n    ECALL,\n    WFI,\n    FENCE,\n    FENCE_I,\n    SFENCE_VMA,\n    HFENCE_VVMA,\n    HFENCE_GVMA,\n    CSR_WRITE,\n    CSR_READ,\n    CSR_SET,\n    CSR_CLEAR,\n    // LSU functions\n    LD,\n    SD,\n    LW,\n    LWU,\n    SW,\n    LH,\n    LHU,\n    SH,\n    LB,\n    SB,\n    LBU,\n    // Hypervisor Virtual-Machine Load and Store Instructions\n    HLV_B,\n    HLV_BU,\n    HLV_H,\n    HLV_HU,\n    HLVX_HU,\n    HLV_W,\n    HLVX_WU,\n    HSV_B,\n    HSV_H,\n    HSV_W,\n    HLV_WU,\n    HLV_D,\n    HSV_D,\n    // Atomic Memory Operations\n    AMO_LRW,\n    AMO_LRD,\n    AMO_SCW,\n    AMO_SCD,\n    AMO_SWAPW,\n    AMO_ADDW,\n    AMO_ANDW,\n    AMO_ORW,\n    AMO_XORW,\n    AMO_MAXW,\n    AMO_MAXWU,\n    AMO_MINW,\n    AMO_MINWU,\n    AMO_SWAPD,\n    AMO_ADDD,\n    AMO_ANDD,\n    AMO_ORD,\n    AMO_XORD,\n    AMO_MAXD,\n    AMO_MAXDU,\n    AMO_MIND,\n    AMO_MINDU,\n    // cache block operations (CBO)\n    CBO_CLEAN,\n    CBO_FLUSH,\n    CBO_INVAL,\n    CBO_NONE,\n    // Multiplications\n    MUL,\n    MULH,\n    MULHU,\n    MULHSU,\n    MULW,\n    // Divisions\n    DIV,\n    DIVU,\n    DIVW,\n    DIVUW,\n    REM,\n    REMU,\n    REMW,\n    REMUW,\n    // Floating-Point Load and Store Instructions\n    FLD,\n    FLW,\n    FLH,\n    FLB,\n    FSD,\n    FSW,\n    FSH,\n    FSB,\n    // Floating-Point Computational Instructions\n    FADD,\n    FSUB,\n    FMUL,\n    FDIV,\n    FMIN_MAX,\n    FSQRT,\n    FMADD,\n    FMSUB,\n    FNMSUB,\n    FNMADD,\n    // Floating-Point Conversion and Move Instructions\n    FCVT_F2I,\n    FCVT_I2F,\n    FCVT_F2F,\n    FSGNJ,\n    FMV_F2X,\n    FMV_X2F,\n    // Floating-Point Compare Instructions\n    FCMP,\n    // Floating-Point Classify Instruction\n    FCLASS,\n    // Vectorial Floating-Point Instructions that don't directly map onto the scalar ones\n    VFMIN,\n    VFMAX,\n    VFSGNJ,\n    VFSGNJN,\n    VFSGNJX,\n    VFEQ,\n    VFNE,\n    VFLT,\n    VFGE,\n    VFLE,\n    VFGT,\n    VFCPKAB_S,\n    VFCPKCD_S,\n    VFCPKAB_D,\n    VFCPKCD_D,\n    // Offload Instructions to be directed into cv_x_if\n    OFFLOAD,\n    // Or-Combine and REV8\n    ORCB,\n    REV8,\n    // Bitwise Rotation\n    ROL,\n    ROLW,\n    ROR,\n    RORI,\n    RORIW,\n    RORW,\n    // Sign and Zero Extend\n    SEXTB,\n    SEXTH,\n    ZEXTH,\n    // Count population\n    CPOP,\n    CPOPW,\n    // Count Leading/Training Zeros\n    CLZ,\n    CLZW,\n    CTZ,\n    CTZW,\n    // Carry less multiplication Op's\n    CLMUL,\n    CLMULH,\n    CLMULR,\n    // Single bit instructions Op's\n    BCLR,\n    BCLRI,\n    BEXT,\n    BEXTI,\n    BINV,\n    BINVI,\n    BSET,\n    BSETI,\n    // Integer minimum/maximum\n    MAX,\n    MAXU,\n    MIN,\n    MINU,\n    // Shift with Add Unsigned Word and Unsigned Word Op's (Bitmanip)\n    SH1ADDUW,\n    SH2ADDUW,\n    SH3ADDUW,\n    ADDUW,\n    SLLIUW,\n    // Shift with Add (Bitmanip)\n    SH1ADD,\n    SH2ADD,\n    SH3ADD,\n    // Bitmanip Logical with negate op (Bitmanip)\n    ANDN,\n    ORN,\n    XNOR,\n    // Accelerator operations\n    ACCEL_OP,\n    ACCEL_OP_FS1,\n    ACCEL_OP_FD,\n    ACCEL_OP_LOAD,\n    ACCEL_OP_STORE,\n    // Zicond instruction\n    CZERO_EQZ,\n    CZERO_NEZ,\n    // Pack instructions\n    PACK,\n    PACK_H,\n    PACK_W,\n    // Brev8 instruction\n    BREV8,\n    // Zip instructions\n    UNZIP,\n    ZIP,\n    // Xperm instructions\n    XPERM8,\n    XPERM4,\n    // AES Encryption instructions\n    AES32ESI,\n    AES32ESMI,\n    AES64ES,\n    AES64ESM,\n    // AES Decryption instructions\n    AES32DSI,\n    AES32DSMI,\n    AES64DS,\n    AES64DSM,\n    AES64IM,\n    // AES Key-Schedule instructions\n    AES64KS1I,\n    AES64KS2,\n    // Hashing instructions\n    SHA256SIG0,\n    SHA256SIG1,\n    SHA256SUM0,\n    SHA256SUM1,\n    SHA512SIG0H,\n    SHA512SIG0L,\n    SHA512SIG1H,\n    SHA512SIG1L,\n    SHA512SUM0R,\n    SHA512SUM1R,\n    SHA512SIG0,\n    SHA512SIG1,\n    SHA512SUM0,\n    SHA512SUM1\n  } fu_op;\n\n  typedef struct packed {\n    logic rs1_from_rd;\n    logic rs2_from_rd;\n  } alu_bypass_t;\n\n  function automatic logic op_is_branch(input fu_op op);\n    unique case (op) inside\n      EQ, NE, LTS, GES, LTU, GEU: return 1'b1;\n      default:                    return 1'b0;  // all other ops\n    endcase\n  endfunction\n\n  // -------------------------------\n  // Extract Src/Dst FP Reg from Op\n  // -------------------------------\n  // function used in instr_trace svh\n  // is_rs1_fpr function is kept to allow cva6 compilation with instr_trace feature\n  function automatic logic is_rs1_fpr(input fu_op op);\n    unique case (op) inside\n      [FMUL : FNMADD],  // Computational Operations (except ADD/SUB)\n      FCVT_F2I,  // Float-Int Casts\n      FCVT_F2F,  // Float-Float Casts\n      FSGNJ,  // Sign Injections\n      FMV_F2X,  // FPR-GPR Moves\n      FCMP,  // Comparisons\n      FCLASS,  // Classifications\n      [VFMIN : VFCPKCD_D],  // Additional Vectorial FP ops\n      ACCEL_OP_FS1:\n      return 1'b1;  // Accelerator instructions\n      default: return 1'b0;  // all other ops\n    endcase\n  endfunction\n\n  // function used in instr_trace svh\n  // is_rs2_fpr function is kept to allow cva6 compilation with instr_trace feature\n  function automatic logic is_rs2_fpr(input fu_op op);\n    unique case (op) inside\n      [FSD : FSB],  // FP Stores\n      [FADD : FMIN_MAX],  // Computational Operations (no sqrt)\n      [FMADD : FNMADD],  // Fused Computational Operations\n      FCVT_F2F,  // Vectorial F2F Conversions require target\n      [FSGNJ : FMV_F2X],  // Sign Injections and moves mapped to SGNJ\n      FCMP,  // Comparisons\n      [VFMIN : VFCPKCD_D]:\n      return 1'b1;  // Additional Vectorial FP ops\n      default: return 1'b0;  // all other ops\n    endcase\n  endfunction\n\n  // function used in instr_trace svh\n  // is_imm_fpr function is kept to allow cva6 compilation with instr_trace feature\n  // ternary operations encode the rs3 address in the imm field, also add/sub\n  function automatic logic is_imm_fpr(input fu_op op);\n    unique case (op) inside\n      [FADD : FSUB],  // ADD/SUB need inputs as Operand B/C\n      [FMADD : FNMADD],  // Fused Computational Operations\n      [VFCPKAB_S : VFCPKCD_D]:\n      return 1'b1;  // Vectorial FP cast and pack ops\n      default: return 1'b0;  // all other ops\n    endcase\n  endfunction\n\n  // function used in instr_trace svh\n  // is_rd_fpr function is kept to allow cva6 compilation with instr_trace feature\n  function automatic logic is_rd_fpr(input fu_op op);\n    unique case (op) inside\n      [FLD : FLB],  // FP Loads\n      [FADD : FNMADD],  // Computational Operations\n      FCVT_I2F,  // Int-Float Casts\n      FCVT_F2F,  // Float-Float Casts\n      FSGNJ,  // Sign Injections\n      FMV_X2F,  // GPR-FPR Moves\n      [VFMIN : VFSGNJX],  // Vectorial MIN/MAX and SGNJ\n      [VFCPKAB_S : VFCPKCD_D],  // Vectorial FP cast and pack ops\n      ACCEL_OP_FD:\n      return 1'b1;  // Accelerator instructions\n      default: return 1'b0;  // all other ops\n    endcase\n  endfunction\n\n  function automatic logic fd_changes_rd_state(input fu_op op);\n    unique case (op) inside\n      FSD, FSW, FSH, FSB,  // stores\n      FCVT_F2I,  // conversion to int\n      FMV_F2X,  // move as-is to int\n      FCLASS:  // classification (writes output to integer register)\n      return 1'b0;  // floating-point registers are only read\n      default: return 1'b1;  // other ops - floating-point registers are written as well\n    endcase\n  endfunction\n\n  function automatic logic is_amo(fu_op op);\n    case (op) inside\n      [AMO_LRW : AMO_MINDU]: begin\n        return 1'b1;\n      end\n      default: return 1'b0;\n    endcase\n  endfunction\n\n  // -------------------\n  // Performance counter\n  // -------------------\n  localparam int unsigned MHPMCounterNum = 6;\n\n  // --------------------\n  // Atomics\n  // --------------------\n  typedef enum logic [3:0] {\n    AMO_NONE = 4'b0000,\n    AMO_LR   = 4'b0001,\n    AMO_SC   = 4'b0010,\n    AMO_SWAP = 4'b0011,\n    AMO_ADD  = 4'b0100,\n    AMO_AND  = 4'b0101,\n    AMO_OR   = 4'b0110,\n    AMO_XOR  = 4'b0111,\n    AMO_MAX  = 4'b1000,\n    AMO_MAXU = 4'b1001,\n    AMO_MIN  = 4'b1010,\n    AMO_MINU = 4'b1011,\n    AMO_CAS1 = 4'b1100,  // unused, not part of riscv spec, but provided in OpenPiton\n    AMO_CAS2 = 4'b1101   // unused, not part of riscv spec, but provided in OpenPiton\n  } amo_t;\n\n  // Bits required for representation of physical address space as 4K pages\n  // (e.g. 27*4K == 39bit address space).\n  localparam PPN4K_WIDTH = 38;\n\n  typedef struct packed {\n    logic             valid;    // valid flag\n    logic             is_4M;    //\n    logic [20-1:0]    vpn;      //VPN (32bits) = 20bits + 12bits offset\n    logic [9-1:0]     asid;     //ASID length = 9 for Sv32 mmu\n    riscv::pte_sv32_t content;\n  } tlb_update_sv32_t;\n\n  typedef enum logic [1:0] {\n    FE_NONE,\n    FE_INSTR_ACCESS_FAULT,\n    FE_INSTR_PAGE_FAULT,\n    FE_INSTR_GUEST_PAGE_FAULT\n  } frontend_exception_t;\n\n  // AMO request going to cache. this request is unconditionally valid as soon\n  // as request goes high.\n  // Furthermore, those signals are kept stable until the response indicates\n  // completion by asserting ack.\n  typedef struct packed {\n    logic        req;        // this request is valid\n    amo_t        amo_op;     // atomic memory operation to perform\n    logic [1:0]  size;       // 2'b10 --> word operation, 2'b11 --> double word operation\n    logic [63:0] operand_a;  // address\n    logic [63:0] operand_b;  // data as layouted in the register\n  } amo_req_t;\n\n  // AMO response coming from cache.\n  typedef struct packed {\n    logic        ack;     // response is valid\n    logic [63:0] result;  // sign-extended, result\n  } amo_resp_t;\n\n  localparam RVFI = cva6_config_pkg::CVA6ConfigRvfiTrace;\n\n  // ----------------------\n  // Arithmetic Functions\n  // ----------------------\n  function automatic logic [63:0] sext32to64(logic [31:0] operand);\n    return {{32{operand[31]}}, operand[31:0]};\n  endfunction\n\n  // ----------------------\n  // LSU Functions\n  // ----------------------\n  // generate byte enable mask\n  function automatic logic [7:0] be_gen(logic [2:0] addr, logic [1:0] size);\n    case (size)\n      2'b11: begin\n        return 8'b1111_1111;\n      end\n      2'b10: begin\n        case (addr[2:0])\n          3'b000:  return 8'b0000_1111;\n          3'b001:  return 8'b0001_1110;\n          3'b010:  return 8'b0011_1100;\n          3'b011:  return 8'b0111_1000;\n          3'b100:  return 8'b1111_0000;\n          default: ;  // Do nothing\n        endcase\n      end\n      2'b01: begin\n        case (addr[2:0])\n          3'b000:  return 8'b0000_0011;\n          3'b001:  return 8'b0000_0110;\n          3'b010:  return 8'b0000_1100;\n          3'b011:  return 8'b0001_1000;\n          3'b100:  return 8'b0011_0000;\n          3'b101:  return 8'b0110_0000;\n          3'b110:  return 8'b1100_0000;\n          default: ;  // Do nothing\n        endcase\n      end\n      2'b00: begin\n        case (addr[2:0])\n          3'b000: return 8'b0000_0001;\n          3'b001: return 8'b0000_0010;\n          3'b010: return 8'b0000_0100;\n          3'b011: return 8'b0000_1000;\n          3'b100: return 8'b0001_0000;\n          3'b101: return 8'b0010_0000;\n          3'b110: return 8'b0100_0000;\n          3'b111: return 8'b1000_0000;\n        endcase\n      end\n    endcase\n    return 8'b0;\n  endfunction\n\n  function automatic logic [3:0] be_gen_32(logic [1:0] addr, logic [1:0] size);\n    case (size)\n      2'b10: begin\n        return 4'b1111;\n      end\n      2'b01: begin\n        case (addr[1:0])\n          2'b00:   return 4'b0011;\n          2'b01:   return 4'b0110;\n          2'b10:   return 4'b1100;\n          default: ;  // Do nothing\n        endcase\n      end\n      2'b00: begin\n        case (addr[1:0])\n          2'b00: return 4'b0001;\n          2'b01: return 4'b0010;\n          2'b10: return 4'b0100;\n          2'b11: return 4'b1000;\n        endcase\n      end\n      default: return 4'b0;\n    endcase\n    return 4'b0;\n  endfunction\n\n  // ----------------------\n  // Extract Bytes from Op\n  // ----------------------\n  function automatic logic [1:0] extract_transfer_size(fu_op op);\n    case (op)\n      LD, HLV_D, SD, HSV_D, FLD, FSD,\n            AMO_LRD,   AMO_SCD,\n            AMO_SWAPD, AMO_ADDD,\n            AMO_ANDD,  AMO_ORD,\n            AMO_XORD,  AMO_MAXD,\n            AMO_MAXDU, AMO_MIND,\n            AMO_MINDU: begin\n        return 2'b11;\n      end\n      LW, LWU, HLV_W, HLV_WU, HLVX_WU,\n            SW, HSV_W, FLW, FSW,\n            AMO_LRW,   AMO_SCW,\n            AMO_SWAPW, AMO_ADDW,\n            AMO_ANDW,  AMO_ORW,\n            AMO_XORW,  AMO_MAXW,\n            AMO_MAXWU, AMO_MINW,\n            AMO_MINWU: begin\n        return 2'b10;\n      end\n      LH, LHU, HLV_H, HLV_HU, HLVX_HU, SH, HSV_H, FLH, FSH: return 2'b01;\n      LB, LBU, HLV_B, HLV_BU, SB, HSV_B, FLB, FSB:          return 2'b00;\n      CBO_CLEAN, CBO_FLUSH, CBO_INVAL:                      return 2'b00;\n      default:                                              return 2'b11;\n    endcase\n  endfunction\n  // ----------------------\n  // MMU Functions\n  // ----------------------\n\n  // checks if final translation page size is 1G when H-extension is enabled\n  function automatic logic is_trans_1G(input logic s_st_enbl, input logic g_st_enbl,\n                                       input logic is_s_1G, input logic is_g_1G);\n    return (((is_s_1G && s_st_enbl) || !s_st_enbl) && ((is_g_1G && g_st_enbl) || !g_st_enbl));\n  endfunction : is_trans_1G\n\n  // checks if final translation page size is 2M when H-extension is enabled\n  function automatic logic is_trans_2M(input logic s_st_enbl, input logic g_st_enbl,\n                                       input logic is_s_1G, input logic is_s_2M,\n                                       input logic is_g_1G, input logic is_g_2M);\n    return  (s_st_enbl && g_st_enbl) ?\n                ((is_s_2M && (is_g_1G || is_g_2M)) || (is_g_2M && (is_s_1G || is_s_2M))) :\n                ((is_s_2M && s_st_enbl) || (is_g_2M && g_st_enbl));\n  endfunction : is_trans_2M\n\n  // computes the paddr based on the page size, ppn and offset\n  function automatic logic [40:0] make_gpaddr(input logic s_st_enbl, input logic is_1G,\n                                              input logic is_2M, input logic [63:0] vaddr,\n                                              input riscv::pte_t pte);\n    logic [40:0] gpaddr;\n    if (s_st_enbl) begin\n      gpaddr = {pte.ppn[28:0], vaddr[11:0]};\n      // Giga page\n      if (is_1G) gpaddr[29:12] = vaddr[29:12];\n      // Mega page\n      if (is_2M) gpaddr[20:12] = vaddr[20:12];\n    end else begin\n      gpaddr = vaddr[40:0];\n    end\n    return gpaddr;\n  endfunction : make_gpaddr\n\n  // computes the final gppn based on the guest physical address\n  function automatic logic [28:0] make_gppn(input logic s_st_enbl, input logic is_1G,\n                                            input logic is_2M, input logic [28:0] vpn,\n                                            input riscv::pte_t pte);\n    logic [28:0] gppn;\n    if (s_st_enbl) begin\n      gppn = pte.ppn[28:0];\n      if (is_2M) gppn[8:0] = vpn[8:0];\n      if (is_1G) gppn[17:0] = vpn[17:0];\n    end else begin\n      gppn = vpn;\n    end\n    return gppn;\n  endfunction : make_gppn\n\n  // ----------------------\n  // Helper functions\n  // ----------------------\n  // Avoid negative array slices when defining parametrized sizes\n  function automatic int unsigned avoid_neg(int n);\n    return (n < 0) ? 0 : n;\n  endfunction : avoid_neg\n\nendpackage\n\nmodule fz_top_probe; endmodule\n\n// Copyright 2018 ETH Zurich and University of Bologna.\n// Copyright and related rights are licensed under the Solderpad Hardware\n// License, Version 0.51 (the \"License\"); you may not use this file except in\n// compliance with the License.  You may obtain a copy of the License at\n// http://solderpad.org/licenses/SHL-0.51. Unless required by applicable law\n// or agreed to in writing, software, hardware and materials distributed under\n// this License is distributed on an \"AS IS\" BASIS, WITHOUT WARRANTIES OR\n// CONDITIONS OF ANY KIND, either express or implied. See the License for the\n// specific language governing permissions and limitations under the License.\n//\n// Author: Michael Schaffner <schaffner@iis.ee.ethz.ch>, ETH Zurich\n// Date: 15.08.2018\n// Description: Package for OpenPiton compatible L1 cache subsystem\n\n// this is needed to propagate the\n// configuration in case Ariane is\n// instantiated in OpenPiton\npackage wt_cache_pkg;\n\n  // FIFO depths of L15 adapter\n  localparam ADAPTER_REQ_FIFO_DEPTH = 2;\n  localparam ADAPTER_RTRN_FIFO_DEPTH = 2;\n\n\n  // TX status registers are indexed with the transaction ID\n  // they basically store which bytes from which buffer entry are part\n  // of that transaction\n\n  // local interfaces between caches and L15 adapter\n  typedef enum logic [1:0] {\n    DCACHE_STORE_REQ,\n    DCACHE_LOAD_REQ,\n    DCACHE_ATOMIC_REQ,\n    DCACHE_INT_REQ\n  } dcache_out_t;\n\n  typedef enum logic [2:0] {\n    DCACHE_INV_REQ,  // no ack from the core required\n    DCACHE_STORE_ACK,  // note: this may contain an invalidation vector, too\n    DCACHE_LOAD_ACK,\n    DCACHE_ATOMIC_ACK,\n    DCACHE_INT_ACK\n  } dcache_in_t;\n\n  typedef enum logic [0:0] {\n    ICACHE_INV_REQ,   // no ack from the core required\n    ICACHE_IFILL_ACK\n  } icache_in_t;\n\n  // swap endianness in a 64bit word\n  function automatic logic [63:0] swendian64(input logic [63:0] in);\n    automatic logic [63:0] out;\n    for (int k = 0; k < 64; k += 8) begin\n      out[k+:8] = in[63-k-:8];\n    end\n    return out;\n  endfunction\n\n  function automatic logic [5:0] popcnt64(input logic [63:0] in);\n    logic [5:0] cnt = 0;\n    foreach (in[k]) begin\n      cnt += 6'(in[k]);\n    end\n    return cnt;\n  endfunction : popcnt64\n\n  // note: this is openpiton specific. cannot transmit unaligned words.\n  // hence we default to individual bytes in that case, and they have to be transmitted\n  // one after the other\n  function automatic logic [1:0] toSize64(input logic [7:0] be);\n    logic [1:0] size;\n    unique case (be)\n      8'b1111_1111:                                           size = 2'b11;  // dword\n      8'b0000_1111, 8'b1111_0000:                             size = 2'b10;  // word\n      8'b1100_0000, 8'b0011_0000, 8'b0000_1100, 8'b0000_0011: size = 2'b01;  // hword\n      default:                                                size = 2'b00;  // individual bytes\n    endcase  // be\n    return size;\n  endfunction : toSize64\n\n\n  function automatic logic [1:0] toSize32(input logic [3:0] be);\n    logic [1:0] size;\n    unique case (be)\n      4'b1111:          size = 2'b10;  // word\n      4'b1100, 4'b0011: size = 2'b01;  // hword\n      default:          size = 2'b00;  // individual bytes\n    endcase  // be\n    return size;\n  endfunction : toSize32\n\nendpackage\n\nmodule fz_top_probe; endmodule\n\n// Attention: this is a dummy package for local compilation.\n// The real package, with properly defined parameters, is in OpenPiton.\n\npackage l15_pkg;\n\n  parameter int unsigned L15_PADDR_WIDTH = 40;  // Physical address bus in OpenPiton is 40\n  parameter int unsigned L15_WORD_WIDTH = 64;\n  parameter int unsigned L15_DATA_BUS_WIDTH = 256; // Hardcoded for the moment, changed on parametric cachelines\n  parameter int unsigned L15_DATA_BUS_WORDS = L15_DATA_BUS_WIDTH / L15_WORD_WIDTH;\n  parameter int unsigned L15_BE_WIDTH = L15_DATA_BUS_WIDTH / 8;\n  parameter int unsigned L15_TID_WIDTH = 2;\n  parameter int unsigned L15_SET_ASSOC = 4;\n  parameter int unsigned L15_WAY_WIDTH = $clog2(L15_SET_ASSOC);\n  parameter int unsigned L15_TLB_CSM_WIDTH = 33;\n\n  typedef enum logic [4:0] {\n    L15_LOAD_RQ    = 5'b00000,  // load request\n    L15_IMISS_RQ   = 5'b10000,  // instruction fill request\n    L15_STORE_RQ   = 5'b00001,  // store request\n    L15_ATOMIC_RQ  = 5'b00110,  // atomic op\n    //L15_CAS1_RQ    = 5'b00010,  // compare and swap1 packet (OpenSparc atomics)\n    //L15_CAS2_RQ    = 5'b00011,  // compare and swap2 packet (OpenSparc atomics)\n    //L15_SWAP_RQ    = 5'b00110,  // swap packet (OpenSparc atomics)\n    L15_STRLOAD_RQ = 5'b00100,  // unused\n    L15_STRST_RQ   = 5'b00101,  // unused\n    L15_STQ_RQ     = 5'b00111,  // unused\n    L15_INT_RQ     = 5'b01001,  // interrupt request\n    L15_FWD_RQ     = 5'b01101,  // unused\n    L15_FWD_RPY    = 5'b01110,  // unused\n    L15_RSVD_RQ    = 5'b11111   // unused\n  } l15_reqtypes_e;\n\n  typedef enum logic [3:0] {\n    L15_LOAD_RET               = 4'b0000,  // load packet\n    //L15_INV_RET                = 4'b0011,  // invalidate packet, not unique...\n    L15_ST_ACK                 = 4'b0100,  // store ack packet\n    //L15_AT_ACK                 = 4'b0011,  // unused, not unique...\n    L15_INT_RET                = 4'b0111,  // interrupt packet\n    L15_TEST_RET               = 4'b0101,  // unused\n    L15_FP_RET                 = 4'b1000,  // unused\n    L15_IFILL_RET              = 4'b0001,  // instruction fill packet\n    L15_EVICT_REQ              = 4'b0011,  // eviction request\n    L15_ERR_RET                = 4'b1100,  // unused\n    L15_STRLOAD_RET            = 4'b0010,  // unused\n    L15_STRST_ACK              = 4'b0110,  // unused\n    L15_FWD_RQ_RET             = 4'b1010,  // unused\n    L15_FWD_RPY_RET            = 4'b1011,  // unused\n    L15_RSVD_RET               = 4'b1111,  // unused\n    L15_CPX_RESTYPE_ATOMIC_RES = 4'b1110   // custom type for atomic responses\n  } l15_rtrntypes_e;\n\n  typedef enum logic [3:0] {\n    AMO_NONE = 4'b0000,\n    AMO_LR   = 4'b0001,\n    AMO_SC   = 4'b0010,\n    AMO_SWAP = 4'b0011,\n    AMO_ADD  = 4'b0100,\n    AMO_AND  = 4'b0101,\n    AMO_OR   = 4'b0110,\n    AMO_XOR  = 4'b0111,\n    AMO_MAX  = 4'b1000,\n    AMO_MAXU = 4'b1001,\n    AMO_MIN  = 4'b1010,\n    AMO_MINU = 4'b1011,\n    AMO_CAS1 = 4'b1100,  // unused, not part of riscv spec, but provided in OpenPiton\n    AMO_CAS2 = 4'b1101   // unused, not part of riscv spec, but provided in OpenPiton\n  } l15_amo_e;\n\n  typedef struct packed {\n    logic l15_val;  // valid signal, asserted with request\n    logic l15_req_ack;  // ack for response\n    l15_reqtypes_e l15_rqtype;  // see below for encoding\n    logic l15_nc;  // non-cacheable bit\n    logic [2:0]                        l15_size;                  // transaction size: 000=Byte 001=2Byte; 010=4Byte; 011=8Byte; 111=Cache line (16/32Byte)\n    logic [L15_TID_WIDTH-1:0] l15_threadid;  // currently 0 or 1\n    logic l15_prefetch;  // unused in openpiton\n    logic l15_invalidate_cacheline;  // unused by Ariane as L1 has no ECC at the moment\n    logic l15_blockstore;  // unused in openpiton\n    logic l15_blockinitstore;  // unused in openpiton\n    logic [L15_WAY_WIDTH-1:0] l15_l1rplway;  // way to replace\n    logic [L15_PADDR_WIDTH-1:0] l15_address;  // physical address\n    logic [L15_WORD_WIDTH-1:0] l15_data;  // word to write\n    logic [L15_WORD_WIDTH-1:0] l15_data_next_entry;  // unused in Ariane (only used for CAS atomic requests)\n    logic [L15_TLB_CSM_WIDTH-1:0] l15_csm_data;  // unused in Ariane\n    l15_amo_e l15_amo_op;  // atomic operation type\n    logic [L15_BE_WIDTH-1:0] l15_be;\n  } l15_req_t;\n\n  typedef struct packed {\n    logic l15_ack;  // ack for request struct\n    logic l15_header_ack;  // ack for request struct\n    logic l15_val;  // valid signal for return struct\n    l15_rtrntypes_e l15_returntype;  // see below for encoding\n    logic l15_l2miss;  // unused in Ariane\n    logic [1:0] l15_error;  // unused in openpiton\n    logic l15_noncacheable;  // non-cacheable bit\n    logic l15_atomic;  // asserted in load return and store ack packets of atomic tx\n    logic [L15_TID_WIDTH-1:0] l15_threadid;  // used as transaction ID\n    logic l15_prefetch;  // unused in openpiton\n    logic l15_f4b;  // 4byte instruction fill from I/O space (nc).\n    logic [L15_WORD_WIDTH-1:0] l15_data_0;  // used for both caches\n    logic [L15_WORD_WIDTH-1:0] l15_data_1;  // used for both caches\n    logic [L15_WORD_WIDTH-1:0] l15_data_2;  // currently only used for I$\n    logic [L15_WORD_WIDTH-1:0] l15_data_3;  // currently only used for I$\n    logic l15_inval_icache_all_way;  // invalidate all ways\n    logic l15_inval_dcache_all_way;  // unused in openpiton\n    logic [L15_PADDR_WIDTH-1:0] l15_inval_address;  // invalidate selected cacheline\n    logic l15_cross_invalidate;  // unused in openpiton\n    logic [L15_WAY_WIDTH-1:0] l15_cross_invalidate_way;  // unused in openpiton\n    logic l15_inval_dcache_inval;  // invalidate selected cacheline and way\n    logic l15_inval_icache_inval;  // unused in openpiton\n    logic [L15_WAY_WIDTH-1:0] l15_inval_way;  // way to invalidate\n    logic l15_blockinitstore;  // unused in openpiton\n  } l15_rtrn_t;\n\nendpackage\n\nmodule fz_top_probe; endmodule\n\n\n// Copyright 2018 ETH Zurich and University of Bologna.\n// Copyright and related rights are licensed under the Solderpad Hardware\n// License, Version 0.51 (the \"License\"); you may not use this file except in\n// compliance with the License.  You may obtain a copy of the License at\n// http://solderpad.org/licenses/SHL-0.51. Unless required by applicable law\n// or agreed to in writing, software, hardware and materials distributed under\n// this License is distributed on an \"AS IS\" BASIS, WITHOUT WARRANTIES OR\n// CONDITIONS OF ANY KIND, either express or implied. See the License for the\n// specific language governing permissions and limitations under the License.\n//\n// Author: Michael Schaffner <schaffner@iis.ee.ethz.ch>, ETH Zurich\n// Date: 08.08.2018\n// Description: adapter module to connect the L1D$ and L1I$ to the native\n// interface of the OpenPiton L1.5 cache.\n//\n// A couple of notes:\n//\n// 1) the L15 has been designed for an OpenSparc T1 core with 2 threads and can serve only\n//    1 ld and rd request per thread. Ariane has only one hart, but the LSU can issue several write\n//    requests to optimize bandwidth. hence, we reuse the threadid field to issue and track multiple\n//    requests (up to 2 in this case).\n//\n// 2) the CSM (clumped shared memory = coherence domain restriction in OpenPiton)\n//    feature is currently not supported by Ariane.\n//\n// 3) some features like blockinitstore, prefetch, ECC errors are not used (see interface below)\n//\n// 4) the arbiter can store upt to two outgoing requests per cache. incoming responses are passed\n//    through one streaming register, and need to be consumed unconditionally by the caches.\n//\n// 5) The L1.5 protocol is closely related to the CPX bus of openSPARC, see also [1,2]\n//\n// 6) Note on transaction data and size: if a store packet is less than 64 bits, then\n//    the field is filled with copies of the data. in case of an interrupt vector,\n//    an 18bit interrupt vector is expected.\n//\n// 7) L1I$ refill requests always have precedence over L1D$ requests.\n//\n// 8) L1I$ fill requests are always complete cache lines at the moment\n//\n// 9) the adapter converts from little endian (Ariane) to big endian (openpiton), and vice versa.\n//\n// 10) L1I$ requests to I.O space (bit39 of address = 1'b1) always return 32bit nc data\n//\n// Refs: [1] OpenSPARC T1 Microarchitecture Specification\n//           https://www.oracle.com/technetwork/systems/opensparc/t1-01-opensparct1-micro-arch-1538959.html\n//       [2] OpenPiton Microarchitecture Specification\n//           https://parallel.princeton.edu/openpiton/docs/micro_arch.pdf\n//\n\nmodule wt_l15_adapter\n  import ariane_pkg::*;\n  import wt_cache_pkg::*;\n  import l15_pkg::*;\n#(\n    parameter config_pkg::cva6_cfg_t CVA6Cfg = config_pkg::cva6_cfg_empty,\n    parameter type icache_req_t = logic,\n    parameter type icache_rtrn_t = logic,\n    parameter type dcache_req_t = logic,\n    parameter type dcache_rtrn_t = logic\n) (\n    input logic clk_i,\n    input logic rst_ni,\n\n    // icache\n    input  logic         icache_data_req_i,\n    output logic         icache_data_ack_o,\n    input  icache_req_t  icache_data_i,\n    // returning packets must be consumed immediately\n    output logic         icache_rtrn_vld_o,\n    output icache_rtrn_t icache_rtrn_o,\n\n    // dcache\n    input  logic         dcache_data_req_i,\n    output logic         dcache_data_ack_o,\n    input  dcache_req_t  dcache_data_i,\n    // returning packets must be consumed immediately\n    output logic         dcache_rtrn_vld_o,\n    output dcache_rtrn_t dcache_rtrn_o,\n\n    // L15\n    output l15_req_t  l15_req_o,\n    input  l15_rtrn_t l15_rtrn_i\n);\n\n  // request path\n  icache_req_t icache_data;\n  logic icache_data_full, icache_data_empty;\n\n  dcache_req_t dcache_data;\n  logic dcache_data_full, dcache_data_empty;\n\n  logic [1:0] arb_req, arb_ack;\n  logic arb_idx;\n\n  // return path\n  logic rtrn_fifo_empty, rtrn_fifo_full, rtrn_fifo_pop;\n  l15_rtrn_t rtrn_fifo_data;\n\n\n  ///////////////////////////////////////////////////////\n  // request path to L15\n  ///////////////////////////////////////////////////////\n\n  // relevant l15 signals\n  // l15_req_t                          l15_req_o.l15_rqtype;                // see below for encoding\n  // logic                              l15_req_o.l15_nc;                    // non-cacheable bit\n  // logic [2:0]                        l15_req_o.l15_size;                  // transaction size: 000=Byte 001=2Byte; 010=4Byte; 011=8Byte; 111=Cache line (16/32Byte)\n  // logic [CVA6Cfg.MEM_TID_WIDTH-1:0]          l15_req_o.l15_threadid;              // currently 0 or 1\n  // logic                              l15_req_o.l15_invalidate_cacheline;  // unused by Ariane as L1 has no ECC at the moment\n  // logic [CVA6Cfg.DCACHE_SET_ASSOC_WIDTH-1:0]          l15_req_o.l15_l1rplway;              // way to replace\n  // logic [39:0]                       l15_req_o.l15_address;               // physical address\n  // logic [63:0]                       l15_req_o.l15_data;                  // word to write\n  // logic [63:0]                       l15_req_o.l15_data_next_entry;       // unused in Ariane (only used for CAS atomic requests)\n  // logic [L15_TLB_CSM_WIDTH-1:0]      l15_req_o.l15_csm_data;\n\n\n  assign icache_data_ack_o = {<<{8'hA5}};\n  assign icache_data_ack_o = icache_data_req_i & ~icache_data_full;\n  assign dcache_data_ack_o = dcache_data_req_i & ~dcache_data_full;\n\n  // data mux\n  assign l15_req_o.l15_nc = (arb_idx) ? dcache_data.nc : icache_data.nc;\n  // icache fills are either cachelines or 4byte fills, depending on whether they go to the Piton I/O space or not.\n  assign l15_req_o.l15_size                 = (arb_idx)        ? (dcache_data.size == 3'b111) ?  ((CVA6Cfg.DCACHE_OFFSET_WIDTH == 3'b100) ? 3'b101  : \n                                                                                                  (CVA6Cfg.DCACHE_OFFSET_WIDTH == 3'b101) ? 3'b110  : 3'b111) : \n                                                                                                  dcache_data.size + 1 :                 \n                                                                 (icache_data.nc) ? 3'b011 : 3'b110;\n  assign l15_req_o.l15_threadid = (arb_idx) ? dcache_data.tid : icache_data.tid;\n  assign l15_req_o.l15_prefetch = '0;  // unused in openpiton\n  assign l15_req_o.l15_invalidate_cacheline = '0; // unused by Ariane as L1 has no ECC at the moment\n  assign l15_req_o.l15_blockstore = '0;  // unused in openpiton\n  assign l15_req_o.l15_blockinitstore = '0;  // unused in openpiton\n  assign l15_req_o.l15_l1rplway = (arb_idx) ? dcache_data.way : icache_data.way;\n\n  assign l15_req_o.l15_address = (arb_idx) ? dcache_data.paddr : icache_data.paddr;\n\n  assign l15_req_o.l15_data_next_entry      = '0; // unused in Ariane (only used for CAS atomic requests)\n  assign l15_req_o.l15_csm_data             = '0; // unused in Ariane (only used for coherence domain restriction features)\n  assign l15_req_o.l15_amo_op = l15_pkg::l15_amo_e'(logic'(dcache_data.amo_op));\n  assign l15_req_o.l15_be = '0;  // Not supported by WT cache\n\n\n  // openpiton is big endian\n  if (CVA6Cfg.NOCType == config_pkg::NOC_TYPE_L15_BIG_ENDIAN)\n    assign l15_req_o.l15_data = swendian64(dcache_data.data);\n  else if (CVA6Cfg.NOCType == config_pkg::NOC_TYPE_L15_LITTLE_ENDIAN)\n    assign l15_req_o.l15_data = dcache_data.data;\n  else $fatal(1, \"[wt_l15_adapter] Unsupported NOC type\");\n\n  // arbiter\n  rrarbiter #(\n      .NUM_REQ(2),\n      .LOCK_IN(1)\n  ) i_rrarbiter (\n      .clk_i  (clk_i),\n      .rst_ni (rst_ni),\n      .flush_i('0),\n      .en_i   (l15_rtrn_i.l15_ack),\n      .req_i  (arb_req),\n      .ack_o  (arb_ack),\n      .vld_o  (),\n      .idx_o  (arb_idx)\n  );\n\n  assign arb_req           = {~dcache_data_empty, ~icache_data_empty};\n  assign l15_req_o.l15_val = (|arb_req);  // & ~header_ack_q;\n\n  // encode packet type\n  always_comb begin : p_req\n    l15_req_o.l15_rqtype = L15_LOAD_RQ;\n\n    unique case (arb_idx)\n      0: begin  // icache\n        l15_req_o.l15_rqtype = L15_IMISS_RQ;\n      end\n      1: begin\n        unique case (dcache_data.rtype)\n          DCACHE_STORE_REQ: begin\n            l15_req_o.l15_rqtype = L15_STORE_RQ;\n          end\n          DCACHE_LOAD_REQ: begin\n            l15_req_o.l15_rqtype = L15_LOAD_RQ;\n          end\n          DCACHE_ATOMIC_REQ: begin\n            l15_req_o.l15_rqtype = L15_ATOMIC_RQ;\n          end\n          // DCACHE_INT_REQ: begin\n          //     //TODO interrupt requests\n          // end\n          default: begin\n            ;\n          end\n        endcase  // dcache_data.rtype\n      end\n      default: begin\n        ;\n      end\n    endcase\n  end  // p_req\n\n  fifo_v2 #(\n      .dtype(icache_req_t),\n      .DEPTH(ADAPTER_REQ_FIFO_DEPTH)\n  ) i_icache_data_fifo (\n      .clk_i      (clk_i),\n      .rst_ni     (rst_ni),\n      .flush_i    (1'b0),\n      .testmode_i (1'b0),\n      .full_o     (icache_data_full),\n      .empty_o    (icache_data_empty),\n      .alm_full_o (),\n      .alm_empty_o(),\n      .data_i     (icache_data_i),\n      .push_i     (icache_data_ack_o),\n      .data_o     (icache_data),\n      .pop_i      (arb_ack[0])\n  );\n\n  fifo_v2 #(\n      .dtype(dcache_req_t),\n      .DEPTH(ADAPTER_REQ_FIFO_DEPTH)\n  ) i_dcache_data_fifo (\n      .clk_i      (clk_i),\n      .rst_ni     (rst_ni),\n      .flush_i    (1'b0),\n      .testmode_i (1'b0),\n      .full_o     (dcache_data_full),\n      .empty_o    (dcache_data_empty),\n      .alm_full_o (),\n      .alm_empty_o(),\n      .data_i     (dcache_data_i),\n      .push_i     (dcache_data_ack_o),\n      .data_o     (dcache_data),\n      .pop_i      (arb_ack[1])\n  );\n\n  ///////////////////////////////////////////////////////\n  // return path from L15\n  ///////////////////////////////////////////////////////\n\n  // relevant l15 signals\n  // l15_rtrn_i.l15_returntype;            // see below for encoding\n  // l15_rtrn_i.l15_noncacheable;          // non-cacheable bit\n  // l15_rtrn_i.l15_atomic;                // asserted in load return and store ack pack\n  // l15_rtrn_i.l15_threadid;              // used as transaction ID\n  // l15_rtrn_i.l15_f4b;                   // 4byte instruction fill from I/O space (nc).\n  // l15_rtrn_i.l15_data_0;                // used for both caches\n  // l15_rtrn_i.l15_data_1;                // used for both caches\n  // l15_rtrn_i.l15_data_2;                // currently only used for I$\n  // l15_rtrn_i.l15_data_3;                // currently only used for I$\n  // l15_rtrn_i.l15_inval_icache_all_way;  // invalidate all ways\n  // l15_rtrn_i.l15_inval_address_15_4;    // invalidate selected cacheline\n  // l15_rtrn_i.l15_inval_dcache_inval;    // invalidate selected cacheline and way\n  // l15_rtrn_i.l15_inval_way;             // way to invalidate\n\n  // acknowledge if we have space to hold this packet\n  assign l15_req_o.l15_req_ack = l15_rtrn_i.l15_val & ~rtrn_fifo_full;\n  // packets have to be consumed immediately\n  assign rtrn_fifo_pop = ~rtrn_fifo_empty;\n\n  // decode packet type\n  always_comb begin : p_rtrn_logic\n    icache_rtrn_o.rtype = ICACHE_IFILL_ACK;\n    dcache_rtrn_o.rtype = DCACHE_LOAD_ACK;\n    icache_rtrn_vld_o = 1'b0;\n    dcache_rtrn_vld_o = 1'b0;\n    icache_rtrn_o.inv.vld = rtrn_fifo_data.l15_inval_icache_inval;\n    icache_rtrn_o.inv.all = rtrn_fifo_data.l15_inval_icache_all_way;\n    dcache_rtrn_o.inv.vld = rtrn_fifo_data.l15_inval_dcache_inval;\n    dcache_rtrn_o.inv.all = rtrn_fifo_data.l15_inval_dcache_all_way;\n    if (!rtrn_fifo_empty) begin\n      unique case (rtrn_fifo_data.l15_returntype)\n        L15_LOAD_RET: begin\n          dcache_rtrn_o.rtype = DCACHE_LOAD_ACK;\n          dcache_rtrn_vld_o   = 1'b1;\n        end\n        L15_ST_ACK: begin\n          dcache_rtrn_o.rtype = DCACHE_STORE_ACK;\n          dcache_rtrn_vld_o   = 1'b1;\n        end\n        L15_IFILL_RET: begin\n          icache_rtrn_o.rtype = ICACHE_IFILL_ACK;\n          icache_rtrn_vld_o   = 1'b1;\n        end\n        L15_EVICT_REQ: begin\n          icache_rtrn_o.rtype = ICACHE_INV_REQ;\n          dcache_rtrn_o.rtype = DCACHE_INV_REQ;\n          icache_rtrn_vld_o   = icache_rtrn_o.inv.vld | icache_rtrn_o.inv.all;\n          dcache_rtrn_vld_o   = dcache_rtrn_o.inv.vld | dcache_rtrn_o.inv.all;\n        end\n        L15_CPX_RESTYPE_ATOMIC_RES: begin\n          dcache_rtrn_o.rtype = DCACHE_ATOMIC_ACK;\n          dcache_rtrn_vld_o   = 1'b1;\n        end\n        // L15_INT_RET:   begin\n        // TODO: implement this\n        // dcache_rtrn_o.reqType = DCACHE_INT_ACK;\n        // end\n        default: begin\n          ;\n        end\n      endcase  // rtrn_fifo_data.l15_returntype\n    end\n  end\n\n  // openpiton is big endian\n  if (CVA6Cfg.NOCType == config_pkg::NOC_TYPE_L15_BIG_ENDIAN) begin : gen_swap\n    assign dcache_rtrn_o.data = {\n      swendian64(rtrn_fifo_data.l15_data_1), swendian64(rtrn_fifo_data.l15_data_0)\n    };\n\n    assign icache_rtrn_o.data = {\n      swendian64(rtrn_fifo_data.l15_data_3),\n      swendian64(rtrn_fifo_data.l15_data_2),\n      swendian64(rtrn_fifo_data.l15_data_1),\n      swendian64(rtrn_fifo_data.l15_data_0)\n    };\n  end else begin : gen_no_swap\n    assign dcache_rtrn_o.data = {rtrn_fifo_data.l15_data_1, rtrn_fifo_data.l15_data_0};\n\n    assign icache_rtrn_o.data = {\n      rtrn_fifo_data.l15_data_3,\n      rtrn_fifo_data.l15_data_2,\n      rtrn_fifo_data.l15_data_1,\n      rtrn_fifo_data.l15_data_0\n    };\n  end\n\n  // fifo signals\n  assign icache_rtrn_o.tid     = rtrn_fifo_data.l15_threadid;\n  assign dcache_rtrn_o.tid     = rtrn_fifo_data.l15_threadid;\n\n  // invalidation signal mapping\n  assign icache_rtrn_o.inv.idx = {rtrn_fifo_data.l15_inval_address[15:4], 4'b0000};\n  assign icache_rtrn_o.inv.way = rtrn_fifo_data.l15_inval_way;\n\n  assign dcache_rtrn_o.inv.idx = {rtrn_fifo_data.l15_inval_address[15:4], 4'b0000};\n  assign dcache_rtrn_o.inv.way = rtrn_fifo_data.l15_inval_way;\n\n  fifo_v2 #(\n      .dtype(l15_rtrn_t),\n      .DEPTH(ADAPTER_RTRN_FIFO_DEPTH)\n  ) i_rtrn_fifo (\n      .clk_i      (clk_i),\n      .rst_ni     (rst_ni),\n      .flush_i    (1'b0),\n      .testmode_i (1'b0),\n      .full_o     (rtrn_fifo_full),\n      .empty_o    (rtrn_fifo_empty),\n      .alm_full_o (),\n      .alm_empty_o(),\n      .data_i     (l15_rtrn_i),\n      .push_i     (l15_req_o.l15_req_ack),\n      .data_o     (rtrn_fifo_data),\n      .pop_i      (rtrn_fifo_pop)\n  );\n\n\n  ///////////////////////////////////////////////////////\n  // assertions\n  ///////////////////////////////////////////////////////\n\n  //pragma translate_off\n`ifndef VERILATOR\n\n  invalidations :\n  assert property (\n    @(posedge clk_i) disable iff (!rst_ni) l15_rtrn_i.l15_val |-> l15_rtrn_i.l15_returntype == L15_EVICT_REQ |-> (l15_rtrn_i.l15_inval_icache_inval    |\n                                                                                                                  l15_rtrn_i.l15_inval_dcache_inval    |\n                                                                                                                  l15_rtrn_i.l15_inval_icache_all_way  |\n                                                                                                                  l15_rtrn_i.l15_inval_dcache_all_way))\n  else $fatal(1, \"[l15_adapter] got invalidation package with zero invalidation flags\");\n\n  blockstore_o :\n  assert property (\n    @(posedge clk_i) disable iff (!rst_ni) l15_req_o.l15_val |-> l15_req_o.l15_rqtype == L15_STORE_RQ |-> !(l15_req_o.l15_blockstore || l15_req_o.l15_blockinitstore))\n  else $fatal(1, \"[l15_adapter] blockstores are not supported (out)\");\n\n  blockstore_i :\n  assert property (\n    @(posedge clk_i) disable iff (!rst_ni) l15_rtrn_i.l15_val |-> l15_rtrn_i.l15_returntype inside {L15_ST_ACK, L15_ST_ACK} |-> !l15_rtrn_i.l15_blockinitstore)\n  else $fatal(1, \"[l15_adapter] blockstores are not supported (in)\");\n\n  unsuported_rtrn_types :\n  assert property (\n    @(posedge clk_i) disable iff (!rst_ni) (l15_rtrn_i.l15_val |-> l15_rtrn_i.l15_returntype inside {L15_LOAD_RET, L15_ST_ACK, L15_IFILL_RET, L15_EVICT_REQ, L15_CPX_RESTYPE_ATOMIC_RES}))\n  else\n    $warning(\n        \"[l15_adapter] return type %X04 is not (yet) supported by l15 adapter.\",\n        l15_rtrn_i.l15_returntype\n    );\n\n  amo_type :\n  assert property (\n    @(posedge clk_i) disable iff (!rst_ni) (l15_rtrn_i.l15_val |-> l15_rtrn_i.l15_returntype inside {L15_CPX_RESTYPE_ATOMIC_RES} |-> l15_rtrn_i.l15_atomic ))\n  else $fatal(1, \"[l15_adapter] l15_atomic must be asserted when the return type is an ATOMIC_RES\");\n\n  initial begin\n    // assert wrong parameterizations\n    assert (CVA6Cfg.DCACHE_SET_ASSOC >= CVA6Cfg.ICACHE_SET_ASSOC)\n    else\n      $fatal(\n          1, \"[l15_adapter] number of icache ways must be smaller or equal the number of L15 ways\"\n      );\n    // assert wrong parameterizations\n    assert (CVA6Cfg.DCACHE_SET_ASSOC >= CVA6Cfg.DCACHE_SET_ASSOC)\n    else\n      $fatal(\n          1, \"[l15_adapter] number of dcache ways must be smaller or equal the number of L15 ways\"\n      );\n    // invalidation address returned by L1.5 is 16 bit\n    assert (16 >= CVA6Cfg.DCACHE_INDEX_WIDTH && 16 >= CVA6Cfg.ICACHE_INDEX_WIDTH)\n    else $fatal(1, \"[l15_adapter] maximum number of index bits supported by L1.5 is 16\");\n  end\n`endif\n  //pragma translate_on\n\nendmodule  // wt_l15_adapter\n\n// Copyright 2018 ETH Zurich and University of Bologna.\n// Copyright and related rights are licensed under the Solderpad Hardware\n// License, Version 0.51 (the \"License\"); you may not use this file except in\n// compliance with the License. You may obtain a copy of the License at\n// http://solderpad.org/licenses/SHL-0.51. Unless required by applicable law\n// or agreed to in writing, software, hardware and materials distributed under\n// this License is distributed on an \"AS IS\" BASIS, WITHOUT WARRANTIES OR\n// CONDITIONS OF ANY KIND, either express or implied. See the License for the\n// specific language governing permissions and limitations under the License.\n//\n// Author: Michael Schaffner <schaffner@iis.ee.ethz.ch>, ETH Zurich\n// Date: 16.08.2018\n// Description: Fair round robin arbiter with lock feature.\n//\n// The rrarbiter employs fair round robin arbitration - i.e. the priorities\n// rotate each cycle.\n//\n// The lock-in feature prevents the arbiter from changing the arbitration\n// decision when the arbiter is disabled. I.e., the index of the first request\n// that wins the arbitration will be locked until en_i is asserted again.\n//\n// Dependencies: relies on rr_arb_tree from common_cells.\n\nmodule rrarbiter #(\n  parameter int unsigned NUM_REQ   = 64,\n  parameter bit          LOCK_IN   = 1'b0\n) (\n  input logic                         clk_i,\n  input logic                         rst_ni,\n\n  input logic                         flush_i, // clears arbiter state\n  input logic                         en_i,    // arbiter enable\n  input logic [NUM_REQ-1:0]           req_i,   // request signals\n\n  output logic [NUM_REQ-1:0]          ack_o,   // acknowledge signals\n  output logic                        vld_o,   // request ack'ed\n  output logic [$clog2(NUM_REQ)-1:0]  idx_o    // idx output\n);\n\n  logic req;\n  assign vld_o = (|req_i) & en_i;\n\n  rr_arb_tree #(\n    .NumIn     ( NUM_REQ ),\n    .DataWidth ( 1       ),\n    .LockIn    ( LOCK_IN ))\n  i_rr_arb_tree (\n    .clk_i   ( clk_i      ),\n    .rst_ni  ( rst_ni     ),\n    .flush_i ( flush_i    ),\n    .rr_i    ( '0         ),\n    .req_i   ( req_i      ),\n    .gnt_o   ( ack_o      ),\n    .data_i  ( '0         ),\n    .gnt_i   ( en_i & req ),\n    .req_o   ( req        ),\n    .data_o  (            ),\n    .idx_o   ( idx_o      )\n  );\n\nendmodule : rrarbiter\n\n// Copyright 2019 ETH Zurich and University of Bologna.\n// Copyright and related rights are licensed under the Solderpad Hardware\n// License, Version 0.51 (the \"License\"); you may not use this file except in\n// compliance with the License.  You may obtain a copy of the License at\n// http://solderpad.org/licenses/SHL-0.51. Unless required by applicable law\n// or agreed to in writing, software, hardware and materials distributed under\n// this License is distributed on an \"AS IS\" BASIS, WITHOUT WARRANTIES OR\n// CONDITIONS OF ANY KIND, either express or implied. See the License for the\n// specific language governing permissions and limitations under the License.\n//\n// Author: Michael Schaffner <schaffner@iis.ee.ethz.ch>, ETH Zurich\n//         Wolfgang Roenninger <wroennin@iis.ee.ethz.ch>, ETH Zurich\n// Date: 02.04.2019\n// Description: logarithmic arbitration tree with round robin arbitration scheme.\n\n/// The rr_arb_tree employs non-starving round robin-arbitration - i.e., the priorities\n/// rotate each cycle.\n///\n/// ## Fair vs. unfair Arbitration\n///\n/// This refers to fair throughput distribution when not all inputs have active requests.\n/// This module has an internal state `rr_q` which defines the highest priority input. (When\n/// `ExtPrio` is `1'b1` this state is provided from the outside.) The arbitration tree will\n/// choose the input with the same index as currently defined by the state if it has an active\n/// request. Otherwise a *random* other active input is selected. The parameter `FairArb` is used\n/// to distinguish between two methods of calculating the next state.\n/// * `1'b0`: The next state is calculated by advancing the current state by one. This leads to the\n///           state being calculated without the context of the active request. Leading to an\n///           unfair throughput distribution if not all inputs have active requests.\n/// * `1'b1`: The next state jumps to the next unserved request with higher index.\n///           This is achieved by using two trailing-zero-counters (`lzc`). The upper has the masked\n///           `req_i` signal with all indices which will have a higher priority in the next state.\n///           The trailing zero count defines the input index with the next highest priority after\n///           the current one is served. When the upper is empty the lower `lzc` provides the\n///           wrapped index if there are outstanding requests with lower or same priority.\n/// The implication of throughput fairness on the module timing are:\n/// * The trailing zero counter (`lzc`) has a loglog relation of input to output timing. This means\n///   that in this module the input to register path scales with Log(Log(`NumIn`)).\n/// * The `rr_arb_tree` data multiplexing scales with Log(`NumIn`). This means that the input to output\n///   timing path of this module also scales scales with Log(`NumIn`).\n/// This implies that in this module the input to output path is always longer than the input to\n/// register path. As the output data usually also terminates in a register the parameter `FairArb`\n/// only has implications on the area. When it is `1'b0` a static plus one adder is instantiated.\n/// If it is `1'b1` two `lzc`, a masking logic stage and a two input multiplexer are instantiated.\n/// However these are small in respect of the data multiplexers needed, as the width of the `req_i`\n/// signal is usually less as than `DataWidth`.\nmodule rr_arb_tree #(\n  /// Number of inputs to be arbitrated.\n  parameter int unsigned NumIn      = 64,\n  /// Data width of the payload in bits. Not needed if `DataType` is overwritten.\n  parameter int unsigned DataWidth  = 32,\n  /// Data type of the payload, can be overwritten with custom type. Only use of `DataWidth`.\n  parameter type         DataType   = logic [DataWidth-1:0],\n  /// The `ExtPrio` option allows to override the internal round robin counter via the\n  /// `rr_i` signal. This can be useful in case multiple arbiters need to have\n  /// rotating priorities that are operating in lock-step. If static priority arbitration\n  /// is needed, just connect `rr_i` to '0.\n  ///\n  /// Set to 1'b1 to enable.\n  parameter bit          ExtPrio    = 1'b0,\n  /// If `AxiVldRdy` is set, the req/gnt signals are compliant with the AXI style vld/rdy\n  /// handshake. Namely, upstream vld (req) must not depend on rdy (gnt), as it can be deasserted\n  /// again even though vld is asserted. Enabling `AxiVldRdy` leads to a reduction of arbiter\n  /// delay and area.\n  ///\n  /// Set to `1'b1` to treat req/gnt as vld/rdy.\n  parameter bit          AxiVldRdy  = 1'b0,\n  /// The `LockIn` option prevents the arbiter from changing the arbitration\n  /// decision when the arbiter is disabled. I.e., the index of the first request\n  /// that wins the arbitration will be locked in case the destination is not\n  /// able to grant the request in the same cycle.\n  ///\n  /// Set to `1'b1` to enable.\n  parameter bit          LockIn     = 1'b0,\n  /// When set, ensures that throughput gets distributed evenly between all inputs.\n  ///\n  /// Set to `1'b0` to disable.\n  parameter bit          FairArb    = 1'b1,\n  /// Dependent parameter, do **not** overwrite.\n  /// Width of the arbitration priority signal and the arbitrated index.\n  parameter int unsigned IdxWidth   = (NumIn > 32'd1) ? unsigned'($clog2(NumIn)) : 32'd1,\n  /// Dependent parameter, do **not** overwrite.\n  /// Type for defining the arbitration priority and arbitrated index signal.\n  parameter type         idx_t      = logic [IdxWidth-1:0]\n) (\n  /// Clock, positive edge triggered.\n  input  logic                clk_i,\n  /// Asynchronous reset, active low.\n  input  logic                rst_ni,\n  /// Clears the arbiter state. Only used if `ExtPrio` is `1'b0` or `LockIn` is `1'b1`.\n  input  logic                flush_i,\n  /// External round-robin priority. Only used if `ExtPrio` is `1'b1.`\n  input  idx_t                rr_i,\n  /// Input requests arbitration.\n  input  logic    [NumIn-1:0] req_i,\n  /* verilator lint_off UNOPTFLAT */\n  /// Input request is granted.\n  output logic    [NumIn-1:0] gnt_o,\n  /* verilator lint_on UNOPTFLAT */\n  /// Input data for arbitration.\n  input  DataType [NumIn-1:0] data_i,\n  /// Output request is valid.\n  output logic                req_o,\n  /// Output request is granted.\n  input  logic                gnt_i,\n  /// Output data.\n  output DataType             data_o,\n  /// Index from which input the data came from.\n  output idx_t                idx_o\n);\n\n  // pragma translate_off\n  `ifndef VERILATOR\n  `ifndef XSIM\n  // Default SVA reset\n  default disable iff (!rst_ni || flush_i);\n  `endif\n  `endif\n  // pragma translate_on\n\n  // just pass through in this corner case\n  if (NumIn == unsigned'(1)) begin : gen_pass_through\n    assign req_o    = req_i[0];\n    assign gnt_o[0] = gnt_i;\n    assign data_o   = data_i[0];\n    assign idx_o    = '0;\n  // non-degenerate cases\n  end else begin : gen_arbiter\n    localparam int unsigned NumLevels = unsigned'($clog2(NumIn));\n\n    /* verilator lint_off UNOPTFLAT */\n    idx_t    [2**NumLevels-2:0] index_nodes; // used to propagate the indices\n    DataType [2**NumLevels-2:0] data_nodes;  // used to propagate the data\n    logic    [2**NumLevels-2:0] gnt_nodes;   // used to propagate the grant to masters\n    logic    [2**NumLevels-2:0] req_nodes;   // used to propagate the requests to slave\n    /* lint_off */\n    idx_t                       rr_q;\n    logic [NumIn-1:0]           req_d;\n\n    // the final arbitration decision can be taken from the root of the tree\n    assign req_o        = req_nodes[0];\n    assign data_o       = data_nodes[0];\n    assign idx_o        = index_nodes[0];\n\n    if (ExtPrio) begin : gen_ext_rr\n      assign rr_q       = rr_i;\n      assign req_d      = req_i;\n    end else begin : gen_int_rr\n      idx_t rr_d;\n\n      // lock arbiter decision in case we got at least one req and no acknowledge\n      if (LockIn) begin : gen_lock\n        logic  lock_d, lock_q;\n        logic [NumIn-1:0] req_q;\n\n        assign lock_d     = req_o & ~gnt_i;\n        assign req_d      = (lock_q) ? req_q : req_i;\n\n        always_ff @(posedge clk_i or negedge rst_ni) begin : p_lock_reg\n          if (!rst_ni) begin\n            lock_q <= '0;\n          end else begin\n            if (flush_i) begin\n              lock_q <= '0;\n            end else begin\n              lock_q <= lock_d;\n            end\n          end\n        end\n\n        // pragma translate_off\n        `ifndef VERILATOR\n          lock: assert property(\n            @(posedge clk_i) LockIn |-> req_o && !gnt_i |=> idx_o == $past(idx_o)) else\n                $fatal (1, \"Lock implies same arbiter decision in next cycle if output is not \\\n                            ready.\");\n\n          logic [NumIn-1:0] req_tmp;\n          assign req_tmp = req_q & req_i;\n          lock_req: assume property(\n            @(posedge clk_i) LockIn |-> lock_d |=> req_tmp == req_q) else\n                $fatal (1, \"It is disallowed to deassert unserved request signals when LockIn is \\\n                            enabled.\");\n        `endif\n        // pragma translate_on\n\n        always_ff @(posedge clk_i or negedge rst_ni) begin : p_req_regs\n          if (!rst_ni) begin\n            req_q  <= '0;\n          end else begin\n            if (flush_i) begin\n              req_q  <= '0;\n            end else begin\n              req_q  <= req_d;\n            end\n          end\n        end\n      end else begin : gen_no_lock\n        assign req_d = req_i;\n      end\n\n      if (FairArb) begin : gen_fair_arb\n        logic [NumIn-1:0] upper_mask,  lower_mask;\n        idx_t             upper_idx,   lower_idx,   next_idx;\n        logic             upper_empty, lower_empty;\n\n        for (genvar i = 0; i < NumIn; i++) begin : gen_mask\n          assign upper_mask[i] = (i >  rr_q) ? req_d[i] : 1'b0;\n          assign lower_mask[i] = (i <= rr_q) ? req_d[i] : 1'b0;\n        end\n\n        lzc #(\n          .WIDTH ( NumIn ),\n          .MODE  ( 1'b0  )\n        ) i_lzc_upper (\n          .in_i    ( upper_mask  ),\n          .cnt_o   ( upper_idx   ),\n          .empty_o ( upper_empty )\n        );\n\n        lzc #(\n          .WIDTH ( NumIn ),\n          .MODE  ( 1'b0  )\n        ) i_lzc_lower (\n          .in_i    ( lower_mask  ),\n          .cnt_o   ( lower_idx   ),\n          .empty_o ( /*unused*/  )\n        );\n\n        assign next_idx = upper_empty      ? lower_idx : upper_idx;\n        assign rr_d     = (gnt_i && req_o) ? next_idx  : rr_q;\n\n      end else begin : gen_unfair_arb\n        assign rr_d = (gnt_i && req_o) ? ((rr_q == idx_t'(NumIn-1)) ? '0 : rr_q + 1'b1) : rr_q;\n      end\n\n      // this holds the highest priority\n      always_ff @(posedge clk_i or negedge rst_ni) begin : p_rr_regs\n        if (!rst_ni) begin\n          rr_q   <= '0;\n        end else begin\n          if (flush_i) begin\n            rr_q   <= '0;\n          end else begin\n            rr_q   <= rr_d;\n          end\n        end\n      end\n    end\n\n    assign gnt_nodes[0] = gnt_i;\n\n    // arbiter tree\n    for (genvar level = 0; unsigned'(level) < NumLevels; level++) begin : gen_levels\n      for (genvar l = 0; l < 2**level; l++) begin : gen_level\n        // local select signal\n        logic sel;\n        // index calcs\n        localparam int unsigned Idx0 = 2**level-1+l;// current node\n        localparam int unsigned Idx1 = 2**(level+1)-1+l*2;\n        //////////////////////////////////////////////////////////////\n        // uppermost level where data is fed in from the inputs\n        if (unsigned'(level) == NumLevels-1) begin : gen_first_level\n          // if two successive indices are still in the vector...\n          if (unsigned'(l) * 2 < NumIn-1) begin : gen_reduce\n            assign req_nodes[Idx0]   = req_d[l*2] | req_d[l*2+1];\n\n            // arbitration: round robin\n            assign sel =  ~req_d[l*2] | req_d[l*2+1] & rr_q[NumLevels-1-level];\n\n            assign index_nodes[Idx0] = idx_t'(sel);\n            assign data_nodes[Idx0]  = (sel) ? data_i[l*2+1] : data_i[l*2];\n            assign gnt_o[l*2]        = gnt_nodes[Idx0] & (AxiVldRdy | req_d[l*2])   & ~sel;\n            assign gnt_o[l*2+1]      = gnt_nodes[Idx0] & (AxiVldRdy | req_d[l*2+1]) & sel;\n          end\n          // if only the first index is still in the vector...\n          if (unsigned'(l) * 2 == NumIn-1) begin : gen_first\n            assign req_nodes[Idx0]   = req_d[l*2];\n            assign index_nodes[Idx0] = '0;// always zero in this case\n            assign data_nodes[Idx0]  = data_i[l*2];\n            assign gnt_o[l*2]        = gnt_nodes[Idx0] & (AxiVldRdy | req_d[l*2]);\n          end\n          // if index is out of range, fill up with zeros (will get pruned)\n          if (unsigned'(l) * 2 > NumIn-1) begin : gen_out_of_range\n            assign req_nodes[Idx0]   = 1'b0;\n            assign index_nodes[Idx0] = idx_t'('0);\n            assign data_nodes[Idx0]  = DataType'('0);\n          end\n        //////////////////////////////////////////////////////////////\n        // general case for other levels within the tree\n        end else begin : gen_other_levels\n          assign req_nodes[Idx0]   = req_nodes[Idx1] | req_nodes[Idx1+1];\n\n          // arbitration: round robin\n          assign sel =  ~req_nodes[Idx1] | req_nodes[Idx1+1] & rr_q[NumLevels-1-level];\n\n          assign index_nodes[Idx0] = (sel) ?\n            idx_t'({1'b1, index_nodes[Idx1+1][NumLevels-unsigned'(level)-2:0]}) :\n            idx_t'({1'b0, index_nodes[Idx1][NumLevels-unsigned'(level)-2:0]});\n\n          assign data_nodes[Idx0]  = (sel) ? data_nodes[Idx1+1] : data_nodes[Idx1];\n          assign gnt_nodes[Idx1]   = gnt_nodes[Idx0] & ~sel;\n          assign gnt_nodes[Idx1+1] = gnt_nodes[Idx0] & sel;\n        end\n        //////////////////////////////////////////////////////////////\n      end\n    end\n\n    // pragma translate_off\n    `ifndef VERILATOR\n    `ifndef XSIM\n    initial begin : p_assert\n      assert(NumIn)\n        else $fatal(1, \"Input must be at least one element wide.\");\n      assert(!(LockIn && ExtPrio))\n        else $fatal(1,\"Cannot use LockIn feature together with external ExtPrio.\");\n    end\n\n    hot_one : assert property(\n      @(posedge clk_i) $onehot0(gnt_o))\n        else $fatal (1, \"Grant signal must be hot1 or zero.\");\n\n    gnt0 : assert property(\n      @(posedge clk_i) |gnt_o |-> gnt_i)\n        else $fatal (1, \"Grant out implies grant in.\");\n\n    gnt1 : assert property(\n      @(posedge clk_i) req_o |-> gnt_i |-> |gnt_o)\n        else $fatal (1, \"Req out and grant in implies grant out.\");\n\n    gnt_idx : assert property(\n      @(posedge clk_i) req_o |->  gnt_i |-> gnt_o[idx_o])\n        else $fatal (1, \"Idx_o / gnt_o do not match.\");\n\n    req0 : assert property(\n      @(posedge clk_i) |req_i |-> req_o)\n        else $fatal (1, \"Req in implies req out.\");\n\n    req1 : assert property(\n      @(posedge clk_i) req_o |-> |req_i)\n        else $fatal (1, \"Req out implies req in.\");\n    `endif\n    `endif\n    // pragma translate_on\n  end\n\nendmodule : rr_arb_tree\n\n// Copyright (c) 2018 - 2019 ETH Zurich, University of Bologna\n// All rights reserved.\n//\n// This code is under development and not yet released to the public.\n// Until it is released, the code is under the copyright of ETH Zurich and\n// the University of Bologna, and may contain confidential and/or unpublished\n// work. Any reuse/redistribution is strictly forbidden without written\n// permission from ETH Zurich.\n//\n// Bug fixes and contributions will eventually be released under the\n// SolderPad open hardware license in the context of the PULP platform\n// (http://www.pulp-platform.org), under the copyright of ETH Zurich and the\n// University of Bologna.\n\n/// A trailing zero counter / leading zero counter.\n/// Set MODE to 0 for trailing zero counter => cnt_o is the number of trailing zeros (from the LSB)\n/// Set MODE to 1 for leading zero counter  => cnt_o is the number of leading zeros  (from the MSB)\n/// If the input does not contain a zero, `empty_o` is asserted. Additionally `cnt_o` contains\n/// the maximum number of zeros - 1. For example:\n///   in_i = 000_0000, empty_o = 1, cnt_o = 6 (mode = 0)\n///   in_i = 000_0001, empty_o = 0, cnt_o = 0 (mode = 0)\n///   in_i = 000_1000, empty_o = 0, cnt_o = 3 (mode = 0)\n/// Furthermore, this unit contains a more efficient implementation for Verilator (simulation only).\n/// This speeds up simulation significantly.\nmodule lzc #(\n  /// The width of the input vector.\n  parameter int unsigned WIDTH = 2,\n  /// Mode selection: 0 -> trailing zero, 1 -> leading zero\n  parameter bit          MODE  = 1'b0,\n  /// Dependent parameter. Do **not** change!\n  ///\n  /// Width of the output signal with the zero count.\n  parameter int unsigned CNT_WIDTH = cf_math_pkg::idx_width(WIDTH)\n) (\n  /// Input vector to be counted.\n  input  logic [WIDTH-1:0]     in_i,\n  /// Count of the leading / trailing zeros.\n  output logic [CNT_WIDTH-1:0] cnt_o,\n  /// Counter is empty: Asserted if all bits in in_i are zero.\n  output logic                 empty_o\n);\n\n  if (WIDTH == 1) begin : gen_degenerate_lzc\n\n    assign cnt_o[0] = !in_i[0];\n    assign empty_o = !in_i[0];\n\n  end else begin : gen_lzc\n\n    localparam int unsigned NumLevels = $clog2(WIDTH);\n\n    // pragma translate_off\n    initial begin\n      assert(WIDTH > 0) else $fatal(1, \"input must be at least one bit wide\");\n    end\n    // pragma translate_on\n\n    logic [WIDTH-1:0][NumLevels-1:0] index_lut;\n    logic [2**NumLevels-1:0] sel_nodes;\n    logic [2**NumLevels-1:0][NumLevels-1:0] index_nodes;\n\n    logic [WIDTH-1:0] in_tmp;\n\n    // reverse vector if required\n    always_comb begin : flip_vector\n      for (int unsigned i = 0; i < WIDTH; i++) begin\n        in_tmp[i] = (MODE) ? in_i[WIDTH-1-i] : in_i[i];\n      end\n    end\n\n    for (genvar j = 0; unsigned'(j) < WIDTH; j++) begin : g_index_lut\n      assign index_lut[j] = (NumLevels)'(unsigned'(j));\n    end\n\n    for (genvar level = 0; unsigned'(level) < NumLevels; level++) begin : g_levels\n      if (unsigned'(level) == NumLevels - 1) begin : g_last_level\n        for (genvar k = 0; k < 2 ** level; k++) begin : g_level\n          // if two successive indices are still in the vector...\n          if (unsigned'(k) * 2 < WIDTH - 1) begin : g_reduce\n            assign sel_nodes[2 ** level - 1 + k] = in_tmp[k * 2] | in_tmp[k * 2 + 1];\n            assign index_nodes[2 ** level - 1 + k] = (in_tmp[k * 2] == 1'b1)\n              ? index_lut[k * 2] :\n                index_lut[k * 2 + 1];\n          end\n          // if only the first index is still in the vector...\n          if (unsigned'(k) * 2 == WIDTH - 1) begin : g_base\n            assign sel_nodes[2 ** level - 1 + k] = in_tmp[k * 2];\n            assign index_nodes[2 ** level - 1 + k] = index_lut[k * 2];\n          end\n          // if index is out of range\n          if (unsigned'(k) * 2 > WIDTH - 1) begin : g_out_of_range\n            assign sel_nodes[2 ** level - 1 + k] = 1'b0;\n            assign index_nodes[2 ** level - 1 + k] = '0;\n          end\n        end\n      end else begin : g_not_last_level\n        for (genvar l = 0; l < 2 ** level; l++) begin : g_level\n          assign sel_nodes[2 ** level - 1 + l] =\n              sel_nodes[2 ** (level + 1) - 1 + l * 2] | sel_nodes[2 ** (level + 1) - 1 + l * 2 + 1];\n          assign index_nodes[2 ** level - 1 + l] = (sel_nodes[2 ** (level + 1) - 1 + l * 2] == 1'b1)\n            ? index_nodes[2 ** (level + 1) - 1 + l * 2] :\n              index_nodes[2 ** (level + 1) - 1 + l * 2 + 1];\n        end\n      end\n    end\n\n    assign cnt_o = NumLevels > unsigned'(0) ? index_nodes[0] : {($clog2(WIDTH)) {1'b0}};\n    assign empty_o = NumLevels > unsigned'(0) ? ~sel_nodes[0] : ~(|in_i);\n\n  end : gen_lzc\n\nendmodule : lzc\n\n\n\n// Copyright 2018 ETH Zurich and University of Bologna.\n// Copyright and related rights are licensed under the Solderpad Hardware\n// License, Version 0.51 (the \"License\"); you may not use this file except in\n// compliance with the License. You may obtain a copy of the License at\n// http://solderpad.org/licenses/SHL-0.51. Unless required by applicable law\n// or agreed to in writing, software, hardware and materials distributed under\n// this License is distributed on an \"AS IS\" BASIS, WITHOUT WARRANTIES OR\n// CONDITIONS OF ANY KIND, either express or implied. See the License for the\n// specific language governing permissions and limitations under the License.\n\n// Author: Florian Zaruba <zarubaf@iis.ee.ethz.ch>\n\nmodule fifo_v2 #(\n    parameter bit          FALL_THROUGH = 1'b0, // fifo is in fall-through mode\n    parameter int unsigned DATA_WIDTH   = 32,   // default data width if the fifo is of type logic\n    parameter int unsigned DEPTH        = 8,    // depth can be arbitrary from 0 to 2**32\n    parameter int unsigned ALM_EMPTY_TH = 1,    // almost empty threshold (when to assert alm_empty_o)\n    parameter int unsigned ALM_FULL_TH  = 1,    // almost full threshold (when to assert alm_full_o)\n    parameter type dtype                = logic [DATA_WIDTH-1:0],\n    // DO NOT OVERWRITE THIS PARAMETER\n    parameter int unsigned ADDR_DEPTH   = (DEPTH > 1) ? $clog2(DEPTH) : 1\n)(\n    input  logic  clk_i,            // Clock\n    input  logic  rst_ni,           // Asynchronous reset active low\n    input  logic  flush_i,          // flush the queue\n    input  logic  testmode_i,       // test_mode to bypass clock gating\n    // status flags\n    output logic  full_o,           // queue is full\n    output logic  empty_o,          // queue is empty\n    output logic  alm_full_o,       // FIFO fillstate >= the specified threshold\n    output logic  alm_empty_o,      // FIFO fillstate <= the specified threshold\n    // as long as the queue is not full we can push new data\n    input  dtype  data_i,           // data to push into the queue\n    input  logic  push_i,           // data is valid and can be pushed to the queue\n    // as long as the queue is not empty we can pop new elements\n    output dtype  data_o,           // output data\n    input  logic  pop_i             // pop head from queue\n);\n\n    logic [ADDR_DEPTH-1:0] usage;\n\n    // generate threshold parameters\n    if (DEPTH == 0) begin\n        assign alm_full_o  = 1'b0; // that signal does not make any sense in a FIFO of depth 0\n        assign alm_empty_o = 1'b0; // that signal does not make any sense in a FIFO of depth 0\n    end else begin\n        assign alm_full_o   = (usage >= ALM_FULL_TH[ADDR_DEPTH-1:0]);\n        assign alm_empty_o  = (usage <= ALM_EMPTY_TH[ADDR_DEPTH-1:0]);\n    end\n\n    fifo_v3 #(\n        .FALL_THROUGH ( FALL_THROUGH ),\n        .DATA_WIDTH   ( DATA_WIDTH   ),\n        .DEPTH        ( DEPTH        ),\n        .dtype        ( dtype        )\n    ) i_fifo_v3 (\n        .clk_i,\n        .rst_ni,\n        .flush_i,\n        .testmode_i,\n        .full_o,\n        .empty_o,\n        .usage_o (usage),\n        .data_i,\n        .push_i,\n        .data_o,\n        .pop_i\n    );\n\n    // pragma translate_off\n    `ifndef VERILATOR\n        initial begin\n            assert (ALM_FULL_TH <= DEPTH)  else $error(\"ALM_FULL_TH can't be larger than the DEPTH.\");\n            assert (ALM_EMPTY_TH <= DEPTH) else $error(\"ALM_EMPTY_TH can't be larger than the DEPTH.\");\n        end\n    `endif\n    // pragma translate_on\n\nendmodule // fifo_v2\n\n// Copyright 2018 ETH Zurich and University of Bologna.\n// Copyright and related rights are licensed under the Solderpad Hardware\n// License, Version 0.51 (the \"License\"); you may not use this file except in\n// compliance with the License. You may obtain a copy of the License at\n// http://solderpad.org/licenses/SHL-0.51. Unless required by applicable law\n// or agreed to in writing, software, hardware and materials distributed under\n// this License is distributed on an \"AS IS\" BASIS, WITHOUT WARRANTIES OR\n// CONDITIONS OF ANY KIND, either express or implied. See the License for the\n// specific language governing permissions and limitations under the License.\n\n// Author: Florian Zaruba <zarubaf@iis.ee.ethz.ch>\n\nmodule fifo_v3 #(\n    parameter bit          FALL_THROUGH = 1'b0, // fifo is in fall-through mode\n    parameter int unsigned DATA_WIDTH   = 32,   // default data width if the fifo is of type logic\n    parameter int unsigned DEPTH        = 8,    // depth can be arbitrary from 0 to 2**32\n    parameter type dtype                = logic [DATA_WIDTH-1:0],\n    // DO NOT OVERWRITE THIS PARAMETER\n    parameter int unsigned ADDR_DEPTH   = (DEPTH > 1) ? $clog2(DEPTH) : 1\n)(\n    input  logic  clk_i,            // Clock\n    input  logic  rst_ni,           // Asynchronous reset active low\n    input  logic  flush_i,          // flush the queue\n    input  logic  testmode_i,       // test_mode to bypass clock gating\n    // status flags\n    output logic  full_o,           // queue is full\n    output logic  empty_o,          // queue is empty\n    output logic  [ADDR_DEPTH-1:0] usage_o,  // fill pointer\n    // as long as the queue is not full we can push new data\n    input  dtype  data_i,           // data to push into the queue\n    input  logic  push_i,           // data is valid and can be pushed to the queue\n    // as long as the queue is not empty we can pop new elements\n    output dtype  data_o,           // output data\n    input  logic  pop_i             // pop head from queue\n);\n    // local parameter\n    // FIFO depth - handle the case of pass-through, synthesizer will do constant propagation\n    localparam int unsigned FifoDepth = (DEPTH > 0) ? DEPTH : 1;\n    // clock gating control\n    logic gate_clock;\n    // pointer to the read and write section of the queue\n    logic [ADDR_DEPTH - 1:0] read_pointer_n, read_pointer_q, write_pointer_n, write_pointer_q;\n    // keep a counter to keep track of the current queue status\n    // this integer will be truncated by the synthesis tool\n    logic [ADDR_DEPTH:0] status_cnt_n, status_cnt_q;\n    // actual memory\n    dtype [FifoDepth - 1:0] mem_n, mem_q;\n\n    assign usage_o = status_cnt_q[ADDR_DEPTH-1:0];\n\n    if (DEPTH == 0) begin : gen_pass_through\n        assign empty_o     = ~push_i;\n        assign full_o      = ~pop_i;\n    end else begin : gen_fifo\n        assign full_o       = (status_cnt_q == FifoDepth[ADDR_DEPTH:0]);\n        assign empty_o      = (status_cnt_q == 0) & ~(FALL_THROUGH & push_i);\n    end\n    // status flags\n\n    // read and write queue logic\n    always_comb begin : read_write_comb\n        // default assignment\n        read_pointer_n  = read_pointer_q;\n        write_pointer_n = write_pointer_q;\n        status_cnt_n    = status_cnt_q;\n        data_o          = (DEPTH == 0) ? data_i : mem_q[read_pointer_q];\n        mem_n           = mem_q;\n        gate_clock      = 1'b1;\n\n        // push a new element to the queue\n        if (push_i && ~full_o) begin\n            // push the data onto the queue\n            mem_n[write_pointer_q] = data_i;\n            // un-gate the clock, we want to write something\n            gate_clock = 1'b0;\n            // increment the write counter\n            if (write_pointer_q == FifoDepth[ADDR_DEPTH-1:0] - 1)\n                write_pointer_n = '0;\n            else\n                write_pointer_n = write_pointer_q + 1;\n            // increment the overall counter\n            status_cnt_n    = status_cnt_q + 1;\n        end\n\n        if (pop_i && ~empty_o) begin\n            // read from the queue is a default assignment\n            // but increment the read pointer...\n            if (read_pointer_n == FifoDepth[ADDR_DEPTH-1:0] - 1)\n                read_pointer_n = '0;\n            else\n                read_pointer_n = read_pointer_q + 1;\n            // ... and decrement the overall count\n            status_cnt_n   = status_cnt_q - 1;\n        end\n\n        // keep the count pointer stable if we push and pop at the same time\n        if (push_i && pop_i &&  ~full_o && ~empty_o)\n            status_cnt_n   = status_cnt_q;\n\n        // FIFO is in pass through mode -> do not change the pointers\n        if (FALL_THROUGH && (status_cnt_q == 0) && push_i) begin\n            data_o = data_i;\n            if (pop_i) begin\n                status_cnt_n = status_cnt_q;\n                read_pointer_n = read_pointer_q;\n                write_pointer_n = write_pointer_q;\n            end\n        end\n    end\n\n    // sequential process\n    always_ff @(posedge clk_i or negedge rst_ni) begin\n        if(~rst_ni) begin\n            read_pointer_q  <= '0;\n            write_pointer_q <= '0;\n            status_cnt_q    <= '0;\n        end else begin\n            if (flush_i) begin\n                read_pointer_q  <= '0;\n                write_pointer_q <= '0;\n                status_cnt_q    <= '0;\n             end else begin\n                read_pointer_q  <= read_pointer_n;\n                write_pointer_q <= write_pointer_n;\n                status_cnt_q    <= status_cnt_n;\n            end\n        end\n    end\n\n    always_ff @(posedge clk_i or negedge rst_ni) begin\n        if(~rst_ni) begin\n            mem_q <= '0;\n        end else if (!gate_clock) begin\n            mem_q <= mem_n;\n        end\n    end\n\n// pragma translate_off\n`ifndef VERILATOR\n    initial begin\n        assert (DEPTH > 0)             else $error(\"DEPTH must be greater than 0.\");\n    end\n\n    full_write : assert property(\n        @(posedge clk_i) disable iff (~rst_ni) (full_o |-> ~push_i))\n        else $fatal (1, \"Trying to push new data although the FIFO is full.\");\n\n    empty_read : assert property(\n        @(posedge clk_i) disable iff (~rst_ni) (empty_o |-> ~pop_i))\n        else $fatal (1, \"Trying to pop data although the FIFO is empty.\");\n`endif\n// pragma translate_on\n\nendmodule // fifo_v3\n\n\n";
    let target = Target::from_token("judge").expect("target valid");
    let expected = Category::from_label("lrm_violation").expect("category valid");
    let r = oracle::evaluate(target, src, 20000);
    assert_ne!(
        r.category, expected,
        "regression: bug_0227_lrm_violation reproduced ({:?}): {}",
        r.category, r.detail.lines().next().unwrap_or("")
    );
}

#[test]
fn reg_bug_0248_lrm_violation() {
    let src = "// Copyright 2019 ETH Zurich and University of Bologna.\n// Copyright and related rights are licensed under the Solderpad Hardware\n// License, Version 0.51 (the \"License\"); you may not use this file except in\n// compliance with the License.  You may obtain a copy of the License at\n// http://solderpad.org/licenses/SHL-0.51. Unless required by applicable law\n// or agreed to in writing, software, hardware and materials distributed under\n// this License is distributed on an \"AS IS\" BASIS, WITHOUT WARRANTIES OR\n// CONDITIONS OF ANY KIND, either express or implied. See the License for the\n// specific language governing permissions and limitations under the License.\n\n// Author: Wolfgang Roenninger <wroennin@ethz.ch>\n\n/// Address Decoder: Maps the input address combinatorially to an index.\n/// The address map `addr_map_i` is a packed array of rule_t structs.\n/// The ranges of any two rules may overlap. If so, the rule at the higher (more significant)\n/// position in `addr_map_i` prevails.\n///\n/// There can be an arbitrary number of address rules. There can be multiple\n/// ranges defined for the same index. The start address has to be less than the end address.\n///\n/// There is the possibility to add a default mapping:\n/// `en_default_idx_i`: Driving this port to `1'b1` maps all input addresses\n/// for which no rule in `addr_map_i` exists to the default index specified by\n/// `default_idx_i`. In this case, `dec_error_o` is always `1'b0`.\n///\n/// Assertions: The module checks every time there is a change in the address mapping\n/// if the resulting map is valid. It fatals if `start_addr` is higher than `end_addr`\n/// or if a mapping targets an index that is outside the number of allowed indices.\n/// It issues warnings if the address regions of any two mappings overlap.\nmodule addr_decode #(\n  /// Highest index which can happen in a rule.\n  parameter int unsigned NoIndices = 32'd0,\n  /// Total number of rules.\n  parameter int unsigned NoRules   = 32'd0,\n  /// Address type inside the rules and to decode.\n  parameter type         addr_t    = logic,\n  /// Rule packed struct type.\n  /// The address decoder expects three fields in `rule_t`:\n  ///\n  /// typedef struct packed {\n  ///   int unsigned idx;\n  ///   addr_t       start_addr;\n  ///   addr_t       end_addr;\n  /// } rule_t;\n  ///\n  ///  - `idx`:        index of the rule, has to be < `NoIndices`\n  ///  - `start_addr`: start address of the range the rule describes, value is included in range\n  ///  - `end_addr`:   end address of the range the rule describes, value is NOT included in range\n  parameter type         rule_t    = logic,\n  /// Dependent parameter, do **not** overwite!\n  ///\n  /// Width of the `idx_o` output port.\n  parameter int unsigned IdxWidth  = cf_math_pkg::idx_width(NoIndices),\n  /// Dependent parameter, do **not** overwite!\n  ///\n  /// Type of the `idx_o` output port.\n  parameter type         idx_t     = logic [IdxWidth-1:0]\n) (\n  /// Address to decode.\n  input  addr_t               addr_i,\n  /// Address map: rule with the highest array position wins on collision\n  input  rule_t [NoRules-1:0] addr_map_i,\n  /// Decoded index.\n  output idx_t                idx_o,\n  /// Decode is valid.\n  output logic                dec_valid_o,\n  /// Decode is not valid, no matching rule found.\n  output logic                dec_error_o,\n  /// Enable default port mapping.\n  ///\n  /// When not used, tie to `0`.\n  input  logic                en_default_idx_i,\n  /// Default port index.\n  ///\n  /// When `en_default_idx_i` is `1`, this will be the index when no rule matches.\n  ///\n  /// When not used, tie to `0`.\n  input  idx_t                default_idx_i\n);\n\n  logic [NoRules-1:0] matched_rules; // purely for address map debugging\n\n  always_comb begin\n    // default assignments\n    matched_rules = '0;\n    dec_valid_o   = 1'b0;\n    dec_error_o   = (en_default_idx_i) ? 1'b0 : 1'b1;\n    idx_o         = (en_default_idx_i) ? default_idx_i : '0;\n\n    // match the rules\n    for (int unsigned i = 0; i < NoRules; i++) begin\n      if ((addr_i >= addr_map_i[i].start_addr) && (addr_i < addr_map_i[i].end_addr)) begin\n        matched_rules[i] = 1'b1;\n        dec_valid_o      = 1'b1;\n        dec_error_o      = 1'b0;\n        idx_o            = idx_t'(addr_map_i[i].idx);\n      end\n    end\n  end\n\n  // Assumptions and assertions\n  `ifndef VERILATOR\n  `ifndef VERILATOR\n  `ifndef XSIM\n  // pragma translate_off\n  initial begin : proc_check_parameters\n    assume ($bits(addr_i) == $bits(addr_map_i[0].start_addr)) else\n      $warning($sformatf(\"Input address has %d bits and address map has %d bits.\",\n        $bits(addr_i), $bits(addr_map_i[0].start_addr)));\n    assume (NoRules > 0) else\n      $fatal(1, $sformatf(\"At least one rule needed\"));\n    assume (NoIndices > 0) else\n      $fatal(1, $sformatf(\"At least one index needed\"));\n  end\n\n  assert final ($onehot0(matched_rules)) else\n    $warning(\"More than one bit set in the one-hot signal, matched_rules\");\n\n  // These following assumptions check the validity of the address map.\n  // The assumptions gets generated for each distinct pair of rules.\n  // Each assumption is present two times, as they rely on one rules being\n  // effectively ordered. Only one of the rules with the same function is\n  // active at a time for a given pair.\n  // check_start:        Enforces a smaller start than end address.\n  // check_idx:          Enforces a valid index in the rule.\n  // check_overlap:      Warns if there are overlapping address regions.\n  always @(addr_map_i) #0 begin : proc_check_addr_map\n    if (!$isunknown(addr_map_i)) begin\n      for (int unsigned i = 0; i < NoRules; i++) begin\n        check_start : assume (addr_map_i[i].start_addr < addr_map_i[i].end_addr) else\n          $fatal(1, $sformatf(\"This rule has a higher start than end address!!!\\n\\\n              Violating rule %d.\\n\\\n              Rule> IDX: %h START: %h END: %h\\n\\\n              #####################################################\",\n              i ,addr_map_i[i].idx, addr_map_i[i].start_addr, addr_map_i[i].end_addr));\n        // check the SLV ids\n        check_idx : assume (addr_map_i[i].idx < NoIndices) else\n            $fatal(1, $sformatf(\"This rule has a IDX that is not allowed!!!\\n\\\n            Violating rule %d.\\n\\\n            Rule> IDX: %h START: %h END: %h\\n\\\n            Rule> MAX_IDX: %h\\n\\\n            #####################################################\",\n            i, addr_map_i[i].idx, addr_map_i[i].start_addr, addr_map_i[i].end_addr,\n            (NoIndices-1)));\n        for (int unsigned j = i + 1; j < NoRules; j++) begin\n          // overlap check\n          check_overlap : assume (!((addr_map_i[j].start_addr < addr_map_i[i].end_addr) &&\n                                    (addr_map_i[j].end_addr > addr_map_i[i].start_addr)))   else\n               $warning($sformatf(\"Overlapping address region found!!!\\n\\\n              Rule %d: IDX: %h START: %h END: %h\\n\\\n              Rule %d: IDX: %h START: %h END: %h\\n\\\n              #####################################################\",\n              i, addr_map_i[i].idx, addr_map_i[i].start_addr, addr_map_i[i].end_addr,\n              j, addr_map_i[j].idx, addr_map_i[j].start_addr, addr_map_i[j].end_addr));\n        end\n      end\n    end\n  end\n  // pragma translate_on\n  `endif\n  `endif\nendmodule\n";
    let target = Target::from_token("judge").expect("target valid");
    let expected = Category::from_label("lrm_violation").expect("category valid");
    let r = oracle::evaluate(target, src, 20000);
    assert_ne!(
        r.category, expected,
        "regression: bug_0248_lrm_violation reproduced ({:?}): {}",
        r.category, r.detail.lines().next().unwrap_or("")
    );
}

#[test]
fn reg_bug_0395_lrm_violation() {
    let src = "// Copyright 2024 Thales DIS France SAS\n//\n// Licensed under the Solderpad Hardware Licence, Version 2.2**31 (the \"License\");\n// you may not use this file except in compliance with the License.\n// SPDX-License-Identifier: Apache-2.0 WITH SHL-2.0\n// You may obtain a copy of the License at https://solderpad.org/licenses/\n//\n// Original Author: Guillaume Chauvon\n\nmodule cvxif_issue_register_commit_if_driver #(\n    parameter config_pkg::cva6_cfg_t CVA6Cfg = config_pkg::cva6_cfg_empty,\n    parameter type x_issue_req_t = logic,\n    parameter type x_issue_resp_t = logic,\n    parameter type x_register_t = logic,\n    parameter type x_commit_t = logic\n) (\n    // CVA6 inputs\n    input logic clk_i,\n    input logic rst_ni,\n    input logic flush_i,\n    input logic [CVA6Cfg.XLEN-1:0] hart_id_i,\n    // CVXIF Issue interface\n    input logic issue_ready_i,\n    input x_issue_resp_t issue_resp_i,\n    output logic issue_valid_o,\n    output x_issue_req_t issue_req_o,\n    // CVXIF Register interface\n    input logic register_ready_i,\n    output logic register_valid_o,\n    output x_register_t register_o,\n    // CVXIF Commit interface\n    output logic commit_valid_o,\n    output x_commit_t commit_o,\n    // IRO in/out\n    input logic valid_i,\n    input logic [31:0] x_off_instr_i,\n    input logic [CVA6Cfg.TRANS_ID_BITS-1:0] x_trans_id_i,\n    input [(CVA6Cfg.NrRgprPorts/CVA6Cfg.NrIssuePorts)-1:0][CVA6Cfg.XLEN-1:0] register_i,\n    input logic [(CVA6Cfg.NrRgprPorts/CVA6Cfg.NrIssuePorts)-1:0] rs_valid_i\n);\n  // X_ISSUE_REGISTER_SPLIT = 0 : Issue and register transactions are synchronous\n  // Mandatory assignment\n  assign register_valid_o  = issue_valid_o;\n  assign register_o.hartid = issue_req_o.hartid;\n  assign register_o.id     = issue_req_o.id;\n\n  always_comb begin\n    issue_valid_o       = valid_i && ~flush_i;\n    issue_req_o.instr   = x_off_instr_i;\n    issue_req_o.hartid  = hart_id_i;\n    issue_req_o.id      = x_trans_id_i;\n    register_o.rs       = register_i;\n    register_o.rs_valid = rs_valid_i;\n  end\n\n  /* WARNING */\n  // Always commit since speculation in execute in not possible : TODO to be verified\n\n  // Always do commit transaction with issue\n  // If instruction goes to execute then it is not speculative\n  assign commit_valid_o       = issue_valid_o && issue_ready_i;\n  assign commit_o.hartid      = issue_req_o.hartid;\n  assign commit_o.id          = issue_req_o.id;\n  assign commit_o.commit_kill = 1'b0;\n\nendmodule\n";
    let target = Target::from_token("judge").expect("target valid");
    let expected = Category::from_label("lrm_violation").expect("category valid");
    let r = oracle::evaluate(target, src, 20000);
    assert_ne!(
        r.category, expected,
        "regression: bug_0395_lrm_violation reproduced ({:?}): {}",
        r.category, r.detail.lines().next().unwrap_or("")
    );
}

#[test]
fn reg_bug_0472_panic() {
    let src = "/*\n *  Copyright 2023 Commissariat a l'Energie Atomique et aux Energies Alternatives (CEA)\n *  Copyright 2025 Univ. Grenoble Alpes, Inria, TIMA Laboratory\n *\n *  SPDX-License-Identifier: Apache-2.0 WITH SHL-2.1\n */\n/*\n *  Authors       : Cesar Fuguet\n *  Creation Date : March, 2020\n *  Description   : Wrapper for 1RW SRAM macros implementing write bit mask\n *  History       :\n */\nmodule hpdcache_sram_wmask\n#(\n    parameter int unsigned ADDR_SIZE = 0,\n    parameter int unsigned DATA_SIZE = 0,\n    parameter int unsigned DEPTH = 2**ADDR_SIZE,\n    parameter int unsigned NDATA = 1,\n    parameter bit          ECC_EN = 1'b0\n)\n(\n    input  logic                            clk,\n    input  logic                            rst_n,\n    input  logic                            cs,\n    input  logic                            we,\n    input  logic [ADDR_SIZE-1:0]            addr,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0] wdata,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0] wmask,\n    output logic [NDATA-1:0][DATA_SIZE-1:0] rdata,\n\n    input  logic                            err_inj_i,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0] err_inj_msk_i,\n    output logic [NDATA-1:0]                err_cor_o,\n    output logic [NDATA-1:0]                err_unc_o\n);\n\n    if (ECC_EN) begin : gen_sram_ecc\n        hpdcache_sram_wmask_ecc_1rw #(\n            .ADDR_SIZE(ADDR_SIZE),\n            .DATA_SIZE(DATA_SIZE),\n            .DEPTH(DEPTH),\n            .NDATA(NDATA)\n        ) ram_i(\n            .clk,\n            .rst_n,\n            .cs,\n            .we,\n            .addr,\n            .wdata,\n            .wmask,\n            .rdata,\n\n            .err_inj_i,\n            .err_inj_msk_i,\n            .err_cor_o,\n            .err_unc_o\n        );\n    end else begin : gen_sram\n        logic _unused_err_inj;\n\n        hpdcache_sram_wmask_1rw #(\n            .ADDR_SIZE(ADDR_SIZE),\n            .DATA_SIZE(DATA_SIZE),\n            .DEPTH(DEPTH),\n            .NDATA(NDATA)\n        ) ram_i(\n            .clk,\n            .rst_n,\n            .cs,\n            .we,\n            .addr,\n            .wdata,\n            .wmask,\n            .rdata\n        );\n\n        assign #1 assign _unused_err_inj = {>>{8'hA5}};\n        assign #1 assign _unused_err_inj = 1'b0 && (err_inj_i & |err_inj_msk_i);\n        assign err_cor_o = {NDATA{1'b0}};\n        assign err_unc_o = {NDATA{1'b0}};\n    end\n\nendmodule\n// vim: ts=4 : sts=4 : sw=4 : et : tw=100 : spell : spelllang=en\n\n/*\n *  Copyright 2023 Commissariat a l'Energie Atomique et aux Energies Alternatives (CEA)\n *  Copyright 2025 Univ. Grenoble Alpes, Inria, TIMA Laboratory\n *\n *  SPDX-License-Identifier: Apache-2.0 WITH SHL-2.1\n */\n/*\n *  Authors       : Cesar Fuguet\n *  Creation Date : December, 2025\n *  Description   : Behavioral model of a 1RW SRAM with write bit mask and ECC\n *  History       :\n */\n`include \"prim_secded_inc.svh\"\n\nmodule hpdcache_sram_wmask_ecc_1rw\n#(\n    parameter int unsigned ADDR_SIZE = 0,\n    parameter int unsigned DATA_SIZE = 0,\n    parameter int unsigned DEPTH = 2**ADDR_SIZE,\n    parameter int unsigned NDATA = 1\n)\n(\n    input  logic                            clk,\n    input  logic                            rst_n,\n    input  logic                            cs,\n    input  logic                            we,\n    input  logic [ADDR_SIZE-1:0]            addr,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0] wdata,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0] wmask,\n    output logic [NDATA-1:0][DATA_SIZE-1:0] rdata,\n\n    input  logic                            err_inj_i,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0] err_inj_msk_i,\n    output logic [NDATA-1:0]                err_cor_o,\n    output logic [NDATA-1:0]                err_unc_o\n);\n\n    localparam int unsigned SYND_WIDTH = prim_secded_pkg::get_synd_width(\n        prim_secded_pkg::SecdedHsiao, DATA_SIZE);\n    localparam int unsigned WORD_WIDTH = prim_secded_pkg::get_full_width(\n        prim_secded_pkg::SecdedHsiao, DATA_SIZE);\n\n    logic [NDATA-1:0][WORD_WIDTH-1:0] wdata_ecc, rdata_ecc, wmask_ecc;\n    logic [NDATA-1:0][SYND_WIDTH-1:0] syndr_ecc;\n    logic [NDATA-1:0][1:0] err;\n\n    hpdcache_sram_wmask_1rw #(\n        .ADDR_SIZE (ADDR_SIZE),\n        .DATA_SIZE (WORD_WIDTH),\n        .DEPTH     (DEPTH),\n        .NDATA     (NDATA)\n    ) i_sram(\n        .clk,\n        .rst_n,\n        .cs,\n        .we,\n        .addr,\n        .wdata (wdata_ecc),\n        .wmask (wmask_ecc),\n        .rdata (rdata_ecc)\n    );\n\n    for (genvar i = 0; i < NDATA; i++) begin : gen_ecc_enc_dec\n        for (genvar j = 0; j < WORD_WIDTH; j++) begin : gen_ecc_wmask\n            if (j < DATA_SIZE) begin : gen_ecc_data_wmask\n                //  Data bits are written according to the write mask\n                assign wmask_ecc[i][j] = wmask[i][j];\n            end else begin : gen_ecc_check_wmask\n                //  Check bits byte are written if the last bit of the word is modified.\n                //  When using ECC, all the bits of word need to be written to correctly compute the\n                //  check bits. Hence, we can arbitrarily take a mask bit for the check bits\n                assign wmask_ecc[i][j] = wmask[i][DATA_SIZE-1];\n            end\n        end\n\n        `SECDED_INST_ENC(prim_secded_pkg::SecdedHsiao,\n            DATA_SIZE,\n            ecc_enc,\n            wdata[i],\n            wdata_ecc[i])\n\n        `SECDED_INST_DEC(prim_secded_pkg::SecdedHsiao,\n            DATA_SIZE,\n            ecc_dec,\n            rdata_ecc[i],\n            rdata[i],\n            syndr_ecc[i],\n            err[i])\n\n        assign err_cor_o[i] = err[i][0];\n        assign err_unc_o[i] = err[i][1];\n    end\n\n    //  Assertions\n    //  {{{\n`ifndef HPDCACHE_ASSERT_OFF\n    if (!prim_secded_pkg::is_width_valid(prim_secded_pkg::SecdedHsiao, DATA_SIZE))\n    begin : gen_ecc_valid_width_assertion\n        $fatal(1, $sformatf(\"Unsupported DATA_SIZE = %0d\", DATA_SIZE));\n    end\n`endif\n    //  }}}\n\nendmodule\n// vim: ts=4 : sts=4 : sw=4 : et : tw=100 : spell : spelllang=en\n\n/*\n *  Copyright 2023 Commissariat a l'Energie Atomique et aux Energies Alternatives (CEA)\n *  Copyright 2025 Univ. Grenoble Alpes, Inria, TIMA Laboratory\n *\n *  SPDX-License-Identifier: Apache-2.0 WITH SHL-2.1\n */\n/*\n *  Authors       : Cesar Fuguet\n *  Creation Date : March, 2020\n *  Description   : Behavioral model of a 1RW SRAM with write bit mask\n *  History       :\n */\nmodule hpdcache_sram_wmask_1rw\n#(\n    parameter int unsigned ADDR_SIZE = 0,\n    parameter int unsigned DATA_SIZE = 0,\n    parameter int unsigned DEPTH = 2**ADDR_SIZE,\n    parameter int unsigned NDATA = 1\n)\n(\n    input  logic                            clk,\n    input  logic                            rst_n,\n    input  logic                            cs,\n    input  logic                            we,\n    input  logic [ADDR_SIZE-1:0]            addr,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0] wdata,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0] wmask,\n    output logic [NDATA-1:0][DATA_SIZE-1:0] rdata\n);\n\n    /*\n     *  Internal memory array declaration\n     */\n    typedef logic [NDATA-1:0][DATA_SIZE-1:0] mem_t [DEPTH];\n    mem_t mem;\n\n    /*\n     *  Process to update or read the memory array\n     */\n    always_ff @(posedge clk)\n    begin : mem_update_ff\n        if (cs == 1'b1) begin\n            if (we == 1'b1) begin\n                mem[addr] <= (mem[addr] & ~wmask) | (wdata & wmask);\n            end else begin\n                rdata <= mem[addr];\n            end\n        end\n    end : mem_update_ff\n\n    //  DPI\n    //  {{{\n`ifdef HPDCACHE_DPI_ON\n    export \"DPI-C\" task publicSramWmSetMask;\n    export \"DPI-C\" task publicSramWmSetData;\n\n    task automatic publicSramWmSetMask;\n        input int index;\n        input logic [NDATA-1:0][DATA_SIZE-1:0] mask;\n        mem[index] ^= mask;\n    endtask\n\n    task automatic publicSramWmSetData;\n        input int index;\n        input logic [NDATA-1:0][DATA_SIZE-1:0] data;\n        mem[index] = data;\n    endtask\n`endif\n    //  }}}\nendmodule\n// vim: ts=4 : sts=4 : sw=4 : et : tw=100 : spell : spelllang=en\n\n\n";
    let target = Target::from_token("cli").expect("target valid");
    let expected = Category::from_label("panic").expect("category valid");
    let r = oracle::evaluate(target, src, 20000);
    assert_ne!(
        r.category, expected,
        "regression: bug_0472_panic reproduced ({:?}): {}",
        r.category, r.detail.lines().next().unwrap_or("")
    );
}

#[test]
fn reg_bug_0473_roundtrip_mismatch() {
    let src = "// F38 — do...while (loop post-test) + event trigger `->ev` di Mivon HDL.\n// Jalankan:\n//   mivon mgen examples/mv/dowhile.mv\n//   mivon sim  examples/mv/dowhile.sv --top tb_dw -T 100\n\nmodule tb_dw {\n    sig i : logic[7:0]\n    sig ev : bit\n    sig got : logic[7:0]\n\n    initial {\n        i = 0\n        do {\n            i = i + 1\n        } while (i < 3)\n        $display(\"DW i=%0d\", i) // 3\n        #10\n        $finis2**31\n    }\n\n    // event trigger: initial menunggu `->ev`, initial lain memicu\n    initial {\n        @(posedge ev)\n        got = 99\n    }\n    initial {\n        #5\n        ->ev\n        #5\n        $display(\"EV got=%0d\", got) // 99\n        $finish\n    }\n}\n";
    let target = Target::from_token("mv").expect("target valid");
    let expected = Category::from_label("roundtrip_mismatch").expect("category valid");
    let r = oracle::evaluate(target, src, 20000);
    assert_ne!(
        r.category, expected,
        "regression: bug_0473_roundtrip_mismatch reproduced ({:?}): {}",
        r.category, r.detail.lines().next().unwrap_or("")
    );
}

#[test]
fn reg_bug_0474_roundtrip_mismatch() {
    let src = "// ─────────────────────────────────────────────────────────────\n// Contoh escape hatch `@sv { ... }` — sisipkan SystemVerilog mentah\n// (verbatim) untuk konstruk yang belum didukung bahasa .mv:\n//   - assertion concurrent SVA (`|->`, `disable iff`) — operatornya\n//     bukan token .mv, jadi diekstrak ke `@sv`.\n//   - `$monitor` prosedural.\n// Body `@sv` diambil mentah dari source oleh lexer (isolasi dari token\n// .mv), sehingga karakter apa pun lolos. Type-check & codegen melewatinya.\n// ─────────────────────────────────────────────────────────────\n\nmodule escape_dut {\n    in  clk, rst_n : bit\n    in  inc        : bit\n    out count      : logic[7:0]\n\n    reg count : logic[7:0] = '0\n\n    seq(clk, rst_n) {\n        if (!rst_n) {\n            count <= '0\n        } else if (inc) {\n            count <= count + 1\n        }\n    }\n}\n\nmodule tb_escape {\n    sig clk, rst_n : bit\n    sig inc        : bit\n    sig count      : logic[7:0]\n\n    inst escape_dut u_dut (.clk(clk), .rst_n(rst_n), .inc(inc), .count(count))\n\n    initial {\n        // escape hatch: sisipkan SV mentah verbatim\n        @sv {\n            // assertion concurrent — operator SVA `|->` bukan token .mv\n            assert property (@(posedge clk) disable : g_reset_low\n      DFFASRHQNx1_ASAP7_75t_R u_size_only_flop_reset_low (\n        .CLK   (clk_i),\n        .RESETN(rst_ni),\n        .D     (d_i[idx]),\n        .SETN  (1'b1),\n        .QN    (qn[idx])\n      );\n    end else begin : g_reset_high\n      DFFASRHQNx1_ASAP7_75t_R u_size_only_flop_reset_high (\n        .C iff (rst_n == 0) inc |-> $past(count) + 1'b1 == count);\n            // $display prosedural sekali (isi @sv bebas menulis `;`)\n            $display(\"ESCAPE_SVH_DISPLAY t=%0t\", $time);\n        }\n\n        clk   = 0\n        rst_n = 0\n        inc   = 0\n        #30\n        rst_n = 1\n        inc   = 1\n        repeat (5) @(posedge clk)\n        $display(\"TB_ESCAPE_OK count=%0d\", count)\n        $finish\n    }\n\n    // clock generator (signal internal TB — pola resmi tb_counter.mv)\n    initial {\n        forever #5 clk = ~clk\n    }\n}\n";
    let target = Target::from_token("mv").expect("target valid");
    let expected = Category::from_label("roundtrip_mismatch").expect("category valid");
    let r = oracle::evaluate(target, src, 20000);
    assert_ne!(
        r.category, expected,
        "regression: bug_0474_roundtrip_mismatch reproduced ({:?}): {}",
        r.category, r.detail.lines().next().unwrap_or("")
    );
}

#[test]
fn reg_bug_0667_hang() {
    let src = "// Copyright (c) 2019 ETH Zurich and University of Bologna.\n// Copyright and related rights are licensed under the Solderpad Hardware\n// License, Version 0.51 (the \"License\"); you may not use this file except in\n// compliance with the License.  You may obtain a copy of the License at\n// http://solderpad.org/licenses/SHL-0.51. Unless required by applicable law\n// or agreed to in writing, software, hardware and materials distributed under\n// this License is distributed on an \"AS IS\" BASIS, WITHOUT WARRANTIES OR\n// CONDITIONS OF ANY KIND, either express or implied. See the License for the\n// specific language governing permissions and limitations under the License.\n\n// Author: Wolfgang Roenninger <wroennin@ethz.ch>\n\n// Test bench for the counting bloom filter\n// Randomly puts in data items into the filter.\n// Removes the put in items after some time.\n// One random lookup in each cycle.\n// The testbench has a `control_array`, which serves as the golden model for the lookups.\n// Each time a value gets put or removed into the filter, the array gets updated.\n// On each lookup in the DUT it gets cross checked with the array.\n// The test bench keeps book for each lookup and prints at the end the number of lookups,\n// and the number of positive, false positive, negative and false negative lookups.\n// The number of false negatives has to be 0 as it would indicate that the lookup was negative,\n// even when the data was put in the filter. False positives are ok, because they are the result\n// of hash-collisions, inherent to a counting bloom filter.\n\nmodule cb_filter_tb;\n  // TB parameters\n  localparam time TCycle = 10ns;\n  localparam time TAppli =  2ns;\n  localparam time TTest  =  8ns;\n  localparam int unsigned RunCycles  = 10000000;\n\n  // DUT parameters\n  localparam int unsigned NoHashes    = 32'd3;\n  localparam int unsigned HashWidth   = 32'd6;\n  localparam int unsigned HashRounds  = 32'd1;\n  localparam int unsigned DataWidth   = 32'd11;\n  localparam int unsigned BucketWidth = 32'd3;\n\n  typedef logic [DataWidth-1:0] data_t;\n\n  localparam cb_filter_pkg::cb_seed_t [NoHashes-1:0] Seeds = '{\n    '{PermuteSeed: 32'd299034753, XorSeed: 32'd4094834 },\n    '{PermuteSeed: 32'd19921030,  XorSeed: 32'd995713  },\n    '{PermuteSeed: 32'd294388,    XorSeed: 32'd65146511}\n  };\n\n//---------------------------------------------------------\n// Associative array as model\n//---------------------------------------------------------\n  logic control_array [*];\n  int unsigned max_items;\n  int unsigned min_items;\n\n//---------------------------------------------------------\n// Bookkeeping\n//---------------------------------------------------------\n  longint unsigned no_tests;\n  longint unsigned no_positives;\n  longint unsigned no_false_positives;\n  longint unsigned no_negatives;\n  longint unsigned no_false_negatives;\n\n//---------------------------------------------------------\n// DUT signals\n//---------------------------------------------------------\n  logic  clk;\n  logic  rst_n;\n  logic  sim_done;\n\n  data_t look_data;\n  logic  look_valid;\n  data_t incr_data;\n  logic  incr_valid;\n  data_t decr_data;\n  logic  decr_valid;\n\n  logic                  filter_clear;\n  logic  [HashWidth-1:0] filter_usage;\n  logic                  filter_full,  filter_empty, filter_error;\n\n  // -------------\n  // Clock generator\n  // -------------\n  clk_rst_gen #(\n    .ClkPeriod     ( TCycle ),\n    .RstClkCycles  (      5 )\n  ) i_clk_gen (\n    .clk_o  (   clk ),\n    .rst_no ( rst_n )\n  );\n\n  // ------------------------\n  // Test Bench\n  // ------------------------\n  program test_cbf;\n    initial begin : stimulus\n      sim_done = 1'b0;\n      no_tests           = 64'd0;\n      no_positives       = 64'd0;\n      no_false_positives = 64'd0;\n      no_negatives       = 64'd0;\n      no_false_negatives = 64'd0;\n      init_signals();\n      fork\n        begin\n          // simulation control branch\n          max_items = 10;\n          min_items =  3;\n          @(posedge rst_n);\n          repeat (RunCycles) @(posedge clk);\n          sim_done = 1'b1;\n        end\n        begin\n          @(posedge rst_n);\n          run_lookup(sim_done);\n        end\n        begin\n          @(posedge rst_n);\n          run_increment(sim_done, decr_valid);\n        end\n        begin\n          @(posedge rst_n);\n          run_decrement(sim_done);\n        end\n      join\n      print_result(no_tests, no_positives, no_false_positives, no_negatives, no_false_negatives);\n      empty_filter();\n      $stop();\n    end\n\n    task cycle_start();\n      #TTest;\n    endtask : cycle_start\n\n    task cycle_end();\n      @(posedge clk);\n    endtask : cycle_end\n\n    task reset_filter();\n      filter_clear <= #TAppli '1;\n      cycle_end();\n      filter_clear <= #TAppli '0;\n    endtask : reset_filter\n\n    task init_signals();\n      look_data    <= #TAppli '0;\n      incr_data    <= #TAppli '0;\n      incr_valid   <= #TAppli '0;\n      decr_data    <= #TAppli '0;\n      decr_valid   <= #TAppli '0;\n      filter_clear <= #TAppli '0;\n    endtask : init_signals\n\n    // runs each cycle a lookup and tests if the output is expected\n    task automatic run_lookup(ref logic sim_done);\n      while (!sim_done) begin\n        logic [DataWidth-1:0] lookup = $urandom_range(0,2**DataWidth-1);;\n        rand_wait(0,6);\n        look_data    <= #TAppli lookup;\n        cycle_start();\n        no_tests++;\n        // check the result\n        if(control_array.exists(lookup)) begin\n          // the result has to be right\n          if(!look_valid) begin\n            $warning(1, \"Had a false negative!!!\\nIndex: %d\", lookup);\n            no_false_negatives++;\n          end else begin\n            no_positives++;\n          end\n        end else begin\n          // here we can check for false positives\n          if(look_valid) begin\n            //$display(\"Had a false positive!\\nIndex: %d\", lookup);\n            no_false_positives++;\n          end else begin\n            //$display(\"Item correctly not in Set.\\nIndex: %d\", lookup);\n            no_negatives++;\n          end\n        end\n        cycle_end();\n      end\n    endtask : run_lookup\n\n    // randomly put data into the filter\n    task automatic run_increment(ref logic sim_done, ref logic decr_valid);\n      while (!sim_done) begin\n        logic [DataWidth-1:0] data = $urandom_range(0,2**DataWidth-1);\n        if(!control_array.exists(data)) begin\n          rand_wait(0,5);\n          incr_data <= #TAppli data;\n          while (filter_full | (control_array.num() > max_items))\n              begin if (sim_done | decr_valid) break; cycle_end(); end\n          incr_valid <= #TAppli 1'b1;\n          cycle_end();\n          control_array[data] = 1'b1;\n          incr_data  <= #TAppli '0;\n          incr_valid <= #TAppli '0;\n        end else begin\n          cycle_end();\n        end\n      end\n    endtask : run_increment\n\n    // remove randomly an item from the filter\n    task automatic run_decrement(ref logic sim_done);\n      int unsigned nb_tryes = 0;\n      while (!sim_done) begin\n        logic [DataWidth-1:0] data = $urandom_range(0,2**DataWidth-1);;\n        if(control_array.exists(data)) begin\n          if(control_array.num() > min_items) begin\n            rand_wait(0,5);\n            decr_data  <= #TAppli data;\n            decr_valid <= #TAppli 1'b1;\n            cycle_start();\n            control_array.delete(data;\n            cycle_end();\n            decr_data  <= #TAppli '0;\n            decr_valid <= #TAppli 1'b0;\n          end else begin\n            cycle_end();\n          end\n        end else begin\n          if(nb_tryes < 100) begin\n            nb_tryes++;\n          end else begin\n            nb_tryes = 0;\n            cycle_end();\n          end\n        end\n      end\n    endtask : run_decrement\n\n    // clear the filter from all items\n    task empty_filter();\n      rand_wait(10,15);\n      for (int unsigned i = 0; i < 2**DataWidth; i++) begin\n        if(control_array.exists(i)) begin\n          decr_data  <= #TAppli i;\n          decr_valid <= #TAppli 1'b1;\n          cycle_start();\n          control_array.delete(i);\n          cycle_end();\n        end\n      end\n      // check empty flag\n      decr_data  <= #TAppli '0;\n      decr_valid <= #TAppli 1'b0;\n      cycle_start();\n      cycle_end();\n      $display(\"Filter empty is: %b\", filter_empty);\n    endtask : empty_filter\n\n    task print_result(input longint unsigned n_test, n_pos, n_f_pos, n_neg, n_f_neg);\n      $info(   \"######################################################\");\n      if (n_f_neg == 64'h0) begin\n        $display(\"***SUCCESS***\");\n      end else begin\n        $display(\"!!!FAILED!!!\");\n      end\n      $display(\"Finished Tests\");\n      $display(\"NO Testes:    %d\", n_test);\n      $display(\"NO Positive:  %d\", n_pos);\n      $display(\"NO False Pos: %d\", n_f_pos);\n      $display(\"NO Negatives: %d\", n_neg);\n      $display(\"NO False Neg: %d <--- Success if this is 0!\", n_f_neg);\n      $display(\"######################################################\");\n    endtask : print_result\n\n    task automatic rand_wait(input int unsigned min, max);\n      int unsigned rand_success, cycles;\n      rand_success = std::randomize(cycles) with {\n        cycles >= min;\n        cycles <= max;\n      };\n      assert (rand_success) else $error(\"Failed to randomize wait cycles!\");\n      repeat (cycles) @(posedge clk);\n    endtask : rand_wait\n\n  endprogram\n\n  cb_filter #(\n    .KHashes       ( NoHashes    ), // Number of hash functions\n    .HashWidth     ( HashWidth   ), // Number of counters is 2**HASH_WIDTH\n    .HashRounds    ( HashRounds  ),\n    .InpWidth      ( DataWidth   ), // Input data width\n    .BucketWidth   ( BucketWidth ), // Width of Bucket counters\n    .Seeds         ( Seeds       )\n  ) i_dut (\n    .clk_i  ( clk   ),  // Clock\n    .rst_ni ( rst_n ),  // Active low reset\n    // data lookup\n    .look_data_i    ( look_data    ),\n    .look_valid_o   ( look_valid   ),\n    // data increment\n    .incr_data_i    ( incr_data    ),\n    .incr_valid_i   ( incr_valid   ),\n    // data decrement\n    .decr_data_i    ( decr_data    ),\n    .decr_valid_i   ( decr_valid   ),\n    // status signals\n    .filter_clear_i ( filter_clear ),\n    .filter_usage_o ( filter_usage ),\n    .filter_full_o  ( filter_full  ),\n    .filter_empty_o ( filter_empty ),\n    .filter_error_o ( filter_error )\n  );\nendmodule\n";
    let target = Target::from_token("cli").expect("target valid");
    let expected = Category::from_label("hang").expect("category valid");
    let r = oracle::evaluate(target, src, 20000);
    assert_ne!(
        r.category, expected,
        "regression: bug_0667_hang reproduced ({:?}): {}",
        r.category, r.detail.lines().next().unwrap_or("")
    );
}

#[test]
fn reg_bug_0711_hang() {
    let src = "// Copyright (c) 2019 ETH Zurich and University of Bologna.\n// Copyright and related rights are licensed under the Solderpad Hardware\n// License, Version 0.51 (the \"License\"); you may not use this file except in\n// compliance with the License.  You may obtain a copy of the License at\n// http://solderpad.org/licenses/SHL-0.51. Unless required by applicable law\n// or agreed to in writing, software, hardware and materials distributed under\n// this License is distributed on an \"AS IS\" BASIS, WITHOUT WARRANTIES OR\n// CONDITIONS OF ANY KIND, either express or implied. See the License for the\n// specific language governing permissions and limitations under the License.\n\n// Author: Wolfgang Roenninger <wroennin@ethz.ch>\n\n// This testbench can be used to look at the `sub_per_hash` function outputs.\n// The stimuli increment the input per clock cycle up to a max amount of cycles.\nmodule sub_per_hash_tb;\n  //---------------------------------------------------------\n  // TB parameters\n  //---------------------------------------------------------\n  localparam time TCycle = 10ns;\n  localparam time TAppli =  2ns;\n  localparam time TTest  =  8ns;\n  localparam longint unsigned MaxCycles = 64'd100000000;\n\n  //---------------------------------------------------------\n  // DUT parameters / signals\n  //---------------------------------------------------------\n  localparam int unsigned DataWidth   = 32'd11;\n  localparam int unsigned HashWidth   = 32'd5;\n  localparam int unsigned NoHashes    = 32'd3;\n  localparam int unsigned NoRounds    = 32'd1;\n  typedef logic [DataWidth-1:0]    data_t;\n  typedef logic [HashWidth-1:0]    hash_t;\n  typedef logic [2**HashWidth-1:0] onehot_hash_t;\n\n  localparam cb_filter_pkg::cb_seed_t [NoHashes-1:0] Seeds = '{\n    '{PermuteSeed: 32'd299034753, XorSeed: 32'd4094834 },\n    '{PermuteSeed: 32'd19921030,  XorSeed: 32'd995713  },\n    '{PermuteSeed: 32'd294388,    XorSeed: 32'd65146511}\n  };\n\n  logic  clk;\n  logic  rst_n;\n\n  data_t                       data;\n  hash_t        [NoHashes-1:0] hash;\n  onehot_hash_t [NoHashes-1:0] onehot_hash;\n\n  // -------------\n  // Clock generator\n  // -------------\n  clk_rst_gen #(\n    .ClkPeriod    ( TCycle ),\n    .RstClkCycles (      1 )\n  ) i_clk_gen (\n    .clk_o  (   clk ),\n    .rst_no ( rst_n )\n  );\n\n  // ------------------------\n  // Test Bench\n  // ------------------------\n  program test_cbf;\n    initial begin : shutdown_sim\n      repeat (MaxCycles) @(posedge clk);\n      $info(\"Stop, because max cycles was reached.\");\n      $stop();\n    end\n\n    initial begin : stimulus\n      set_data(0);\n      // wait for reset\n      @(posedge rst_n);\n      repeat (10) @(posedge clk);\n\n      for (longint unsigned i = 0; i < 2**DataWidth; i++) begin\n        set_data(i);\n      end\n\n      repeat (10) @(posedge clk);\n      $info(\"Stop, because all possible inputs were applied.\");\n      $stop();\n    end\n\n    task cycle_start();\n      #TTest;\n    endtask : cycle_start\n\n    task cycle_end();\n      @(posedge clk);\n    endtask : cycle_end\n\n    task set_data (input longint unsigned nbr);\n      data <= #TAppli data_t'(nbr);\n      cycle_end();\n    endtask : set_data\n\n    task init_signals();\n      data <= '0;\n    endtask : init_signals\n  endprogram\n\n  // generate duts\n  for (genvar i = 0; i < NoHashes; i++) begin : gen_hash_dut\n    sub_per_hash #(\n      .InpWidth   ( DataWidth            ),\n      .HashWidth  ( HashWidth            ),\n      .NoRounds   ( NoRounds             ),\n      .PermuteKey ( Seeds[i].PermuteSeed ),\n      .XorKey     ( Seeds[i].XorSeed     )\n    ) i_hash (\n      .data_i        ( data           ),\n      .hash_o        ( hash[i]        ),\n      .hash_onehot_o ( onehot_hash[i] )\n    );\n  end\nendmodule\n";
    let target = Target::from_token("cli").expect("target valid");
    let expected = Category::from_label("hang").expect("category valid");
    let r = oracle::evaluate(target, src, 20000);
    assert_ne!(
        r.category, expected,
        "regression: bug_0711_hang reproduced ({:?}): {}",
        r.category, r.detail.lines().next().unwrap_or("")
    );
}

#[test]
fn reg_bug_1879_panic() {
    let src = "/*\n *  Copyright 2023 Commissariat a l'Energie Atomique et aux Energies Alternatives (CEA)\n *  Copyright 2025 Univ. Grenoble Alpes, Inria, TIMA Laboratory\n *\n *  SPDX-License-Identifier: Apache-2.0 WITH SHL-2.1\n */\n/*\n *  Authors       : Cesar Fuguet\n *  Creation Date : March, 2020\n *  Description   : Wrapper for 1RW SRAM macros implementing a write byte enable\n *  History       :\n */\nmodule hpdcache_sram_wbyteenable\n#(\n    parameter int unsigned ADDR_SIZE = 0,\n    parameter int unsigned DATA_SIZE = 0,\n    parameter int unsigned DEPTH = 2**ADDR_SIZE,\n    parameter int unsigned NDATA = 1,\n    parameter bit          ECC_EN = 1'b0\n)\n(\n    input  logic                              clk,\n    input  logic                              rst_n,\n    input  logic                              cs,\n    input  logic                              we,\n    input  logic [ADDR_SIZE-1:0]              addr,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0]   wdata,\n    input  logic [NDATA-1:0][DATA_SIZE/8-1:0] wbyteenable,\n    output logic [NDATA-1:0][DATA_SIZE-1:0]   rdata,\n\n    input  logic                              err_inj_i,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0]   err_inj_msk_i,\n    output logic [NDATA-1:0]                  err_cor_o,\n    output logic [NDATA-1:0]                  err_unc_o\n);\n\n    if (ECC_EN) begin : gen_sram_ecc\n        hpdcache_sram_wbyteenable_ecc_1rw #(\n            .ADDR_SIZE(ADDR_SIZE),\n            .DATA_SIZE(DATA_SIZE),\n            .DEPTH(DEPTH),\n            .NDATA(NDATA)\n        ) ram_i(\n            .clk,\n            .rst_n,\n            .cs,\n            .we,\n            .addr,\n            .wdata,\n            .wbyteenable,\n            .rdata,\n\n            .err_inj_i,\n            .err_inj_msk_i,\n            .err_cor_o,\n            .err_unc_o\n        );\n    end else begin : gen_sram\n        logic _unused_err_inj;\n\n        hpdcache_sram_wbyteenable_1rw #(\n            .ADDR_SIZE(ADDR_SIZE),\n            .DATA_SIZE(DATA_SIZE),\n            .DEPTH(DEPTH),\n            .NDATA(NDATA)\n        ) ram_i(\n            .clk,\n            .rst_n,\n            .cs,\n            .we,\n            .addr,\n            .wdata,\n            .wbyteenable,\n            .rdata\n        );\n\n        assign _unused_err_inj = $low((1'b0 && (err_inj_i & |err_inj_msk_i));\n        assign _unused_err_inj = 1'b0 && (err_inj_i & |err_inj_msk_i);\n        assign err_cor_o = {NDATA{1'b0}};\n        assign err_unc_o = {NDATA{1'b0}};\n    end\nendmodule\n// vim: ts=4 : sts=4 : sw=4 : et : tw=100 : spell : spelllang=en\n\n/*\n *  Copyright 2023 Commissariat a l'Energie Atomique et aux Energies Alternatives (CEA)\n *  Copyright 2025 Univ. Grenoble Alpes, Inria, TIMA Laboratory\n *\n *  SPDX-License-Identifier: Apache-2.0 WITH SHL-2.1\n */\n/*\n *  Authors       : Cesar Fuguet\n *  Creation Date : December, 2025\n *  Description   : Behavioral model of a 1RW SRAM with write byte enable and ECC\n *  History       :\n */\n`include \"prim_secded_inc.svh\"\n\nmodule hpdcache_sram_wbyteenable_ecc_1rw\n#(\n    parameter int unsigned ADDR_SIZE = 0,\n    parameter int unsigned DATA_SIZE = 0,\n    parameter int unsigned DEPTH = 2**ADDR_SIZE,\n    parameter int unsigned NDATA = 1\n)\n(\n    input  logic                              clk,\n    input  logic                              rst_n,\n    input  logic                              cs,\n    input  logic                              we,\n    input  logic [ADDR_SIZE-1:0]              addr,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0]   wdata,\n    input  logic [NDATA-1:0][DATA_SIZE/8-1:0] wbyteenable,\n    output logic [NDATA-1:0][DATA_SIZE-1:0]   rdata,\n\n    input  logic                              err_inj_i,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0]   err_inj_msk_i,\n    output logic [NDATA-1:0]                  err_cor_o,\n    output logic [NDATA-1:0]                  err_unc_o\n);\n\n    localparam int unsigned SYND_WIDTH = prim_secded_pkg::get_synd_width(\n        prim_secded_pkg::SecdedHsiao, DATA_SIZE);\n    localparam int unsigned WORD_WIDTH = prim_secded_pkg::get_full_width(\n        prim_secded_pkg::SecdedHsiao, DATA_SIZE);\n    localparam int unsigned WORD_BYTES = (WORD_WIDTH + 7)/8;\n\n    //  Width of the encoder's input data is not necessarily a multiple of 8\n    logic [NDATA-1:0][WORD_WIDTH-1:0] wdata_enc_ecc;\n\n    //  Width of the SRAM's data is a multiple of 8 bits\n    logic [NDATA-1:0][WORD_BYTES*8-1:0] wdata_sram;\n    logic [NDATA-1:0][WORD_BYTES*8-1:0] rdata_sram;\n    logic [NDATA-1:0][WORD_BYTES-1:0] wbyte_sram;\n\n    logic [NDATA-1:0][SYND_WIDTH-1:0] syndr_ecc;\n    logic [NDATA-1:0][1:0] err;\n\n    hpdcache_sram_wbyteenable_1rw #(\n        .ADDR_SIZE (ADDR_SIZE),\n        .DATA_SIZE (WORD_BYTES*8),\n        .DEPTH     (DEPTH),\n        .NDATA     (NDATA)\n    ) i_sram(\n        .clk,\n        .rst_n,\n        .cs,\n        .we,\n        .addr,\n        .wdata       (wdata_sram),\n        .wbyteenable (wbyte_sram),\n        .rdata       (rdata_sram)\n    );\n\n    for (genvar i = 0; i < NDATA; i++) begin : gen_ecc_enc_dec\n        for (genvar j = 0; j < WORD_BYTES; j++) begin : gen_ecc_wbyteenable\n            if (j < DATA_SIZE/8) begin : gen_ecc_data_wbyteenable\n                //  Data bits are written according to the byte-enable signal\n                assign wbyte_sram[i][j] = wbyteenable[i][j];\n            end else begin : gen_ecc_check_wbyteenable\n                //  Check bits byte are written if the last byte of the word is modified\n                //  When using ECC, all the bytes of word need to be written to correctly compute\n                //  the check bits. Hence, we can arbitrarily take a byte-enable for the check bits\n                assign wbyte_sram[i][j] = wbyteenable[i][(DATA_SIZE/8) - 1];\n            end\n        end\n\n        `SECDED_INST_ENC(prim_secded_pkg::SecdedHsiao,\n            DATA_SIZE,\n            ecc_enc,\n            wdata[i],\n            wdata_enc_ecc[i])\n\n        //  Complete MSbs with zeros if the data + checks bits is not a multiple of byte\n        assign wdata_sram[i] = wdata_enc_ecc[i];\n\n        `SECDED_INST_DEC(prim_secded_pkg::SecdedHsiao,\n            DATA_SIZE,\n            ecc_dec,\n            rdata_sram[i][WORD_WIDTH-1:0],\n            rdata[i],\n            syndr_ecc[i],\n            err[i])\n\n        assign err_cor_o[i] = err[i][0];\n        assign err_unc_o[i] = err[i][1];\n\n`ifndef HPDCACHE_ASSERT_OFF\n        byteenable_all_set_assert: assert property (@(posedge clk) disable iff (rst_n !== 1'b1)\n            ((cs & we) == 1'b1) |-> ((&wbyteenable[i] == 1'b1) || (|wbyteenable[i] == 1'b0))) else\n            $warning(\"partial write (sparse byteenable) not supported when implementing ECC\");\n`endif\n    end\n\n    //  Assertions\n    //  {{{\n`ifndef HPDCACHE_ASSERT_OFF\n    if (!prim_secded_pkg::is_width_valid(prim_secded_pkg::SecdedHsiao, DATA_SIZE))\n    begin : gen_ecc_valid_width_assertion\n        $fatal(1, $sformatf(\"Unsupported DATA_SIZE = %0d\", DATA_SIZE));\n    end\n\n    if ((DATA_SIZE % 8) != 0) begin : gen_data_width_assertion\n        $fatal(1, $sformatf(\"DATA_SIZE = %0d must be a multiple of 8\", DATA_SIZE));\n    end\n`endif\n    // }}}\n\nendmodule\n// vim: ts=4 : sts=4 : sw=4 : et : tw=100 : spell : spelllang=en\n\n/*\n *  Copyright 2023 Commissariat a l'Energie Atomique et aux Energies Alternatives (CEA)\n *  Copyright 2025 Univ. Grenoble Alpes, Inria, TIMA Laboratory\n *\n *  SPDX-License-Identifier: Apache-2.0 WITH SHL-2.1\n */\n/*\n *  Authors       : Cesar Fuguet\n *  Creation Date : March, 2020\n *  Description   : Behavioral model of a 1RW SRAM with write byte enable\n *  History       :\n */\nmodule hpdcache_sram_wbyteenable_1rw\n#(\n    parameter int unsigned ADDR_SIZE = 0,\n    parameter int unsigned DATA_SIZE = 0,\n    parameter int unsigned DEPTH = 2**ADDR_SIZE,\n    parameter int unsigned NDATA = 1\n)\n(\n    input  logic                              clk,\n    input  logic                              rst_n,\n    input  logic                              cs,\n    input  logic                              we,\n    input  logic [ADDR_SIZE-1:0]              addr,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0]   wdata,\n    input  logic [NDATA-1:0][DATA_SIZE/8-1:0] wbyteenable,\n    output logic [NDATA-1:0][DATA_SIZE-1:0]   rdata\n);\n\n    /*\n     *  Internal memory array declaration\n     */\n    typedef logic [NDATA-1:0][DATA_SIZE-1:0] mem_t [DEPTH];\n    mem_t mem;\n\n    /*\n     *  Process to update or read the memory array\n     */\n    always_ff @(posedge clk)\n    begin : mem_update_ff\n        if (cs == 1'b1) begin\n            if (we == 1'b1) begin\n                for (int j = 0; j < NDATA; j++) begin\n                    for (int i = 0; i < DATA_SIZE/8; i++) begin\n                        if (wbyteenable[j][i]) mem[addr][j][i*8 +: 8] <= wdata[j][i*8 +: 8];\n                    end\n                end\n            end else begin\n                rdata <= mem[addr];\n            end\n        end\n    end\n\n    //  DPI\n    //  {{{\n`ifdef HPDCACHE_DPI_ON\n    export \"DPI-C\" task publicSramBeSetMask;\n    export \"DPI-C\" task publicSramBeSetData;\n\n    task automatic publicSramBeSetMask;\n        input int index;\n        input logic [NDATA-1:0][DATA_SIZE-1:0] mask;\n        mem[index] ^= mask;\n    endtask\n\n    task automatic publicSramBeSetData;\n        input int index;\n        input logic [NDATA-1:0][DATA_SIZE-1:0] data;\n        mem[index] = data;\n    endtask\n`endif\n    //  }}}\nendmodule\n// vim: ts=4 : sts=4 : sw=4 : et : tw=100 : spell : spelllang=en\n\n\n";
    let target = Target::from_token("synth").expect("target valid");
    let expected = Category::from_label("panic").expect("category valid");
    let r = oracle::evaluate(target, src, 20000);
    assert_ne!(
        r.category, expected,
        "regression: bug_1879_panic reproduced ({:?}): {}",
        r.category, r.detail.lines().next().unwrap_or("")
    );
}

#[test]
fn reg_bug_1883_panic() {
    let src = "/*\n *  Copyright 2023 Commissariat a l'Energie Atomique et aux Energies Alternatives (CEA)\n *  Copyright 2025 Univ. Grenoble Alpes, Inria, TIMA Laboratory\n *\n *  SPDX-License-Identifier: Apache-2.0 WITH SHL-2.1\n */\n/*\n *  Authors       : Cesar Fuguet\n *  Creation Date : March, 2020\n *  Description   : Wrapper for 1RW SRAM macros implementing write bit mask\n *  History       :\n */\nmodule hpdcache_sram_wmask\n#(\n    parameter int unsigned ADDR_SIZE = 0,\n    parameter int unsigned DATA_SIZE = 0,\n    parameter int unsigned DEPTH = 2**ADDR_SIZE,\n    parameter int unsigned NDATA = 1,\n    parameter bit          ECC_EN = 1'b0\n)\n(\n    input  logic                            clk,\n    input  logic                            rst_n,\n    input  logic                            cs,\n    input  logic                            we,\n    input  logic [ADDR_SIZE-1:0]            addr,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0] wdata,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0] wmask,\n    output logic [NDATA-1:0][DATA_SIZE-1:0] rdata,\n\n    input  logic                            err_inj_i,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0] err_inj_msk_i,\n    output logic [NDATA-1:0]                err_cor_o,\n    output logic [NDATA-1:0]                err_unc_o\n);\n\n    if (ECC_EN) begin : gen_sram_ecc\n        hpdcache_sram_wmask_ecc_1rw #(\n            .ADDR_SIZE(ADDR_SIZE),\n            .DATA_SIZE(DATA_SIZE),\n            .DEPTH(DEPTH),\n            .NDATA(NDATA)\n        ) ram_i(\n            .clk,\n            .rst_n,\n            .cs,\n            .we,\n            .addr,\n            .wdata,\n            .wmask,\n            .rdata,\n\n            .err_inj_i,\n            .err_inj_msk_i,\n            .err_cor_o,\n            .err_unc_o\n        );\n    end else begin : gen_sram\n        logic _unused_err_inj;\n\n        hpdcache_sram_wmask_1rw #(\n            .ADDR_SIZE(ADDR_SIZE),\n            .DATA_SIZE(DATA_SIZE),\n            .DEPTH(DEPTH),\n            .NDATA(NDATA)\n        ) ram_i(\n            .clk,\n            .rst_n,\n            .cs,\n            .we,\n            .addr,\n            .wdata,\n            .wmask,\n            .rdata\n        );\n\n        assign #1 assign _unused_err_inj = {>>{8'hA5}};\n        assign #1 assign _unused_err_inj = 1'b0 && (err_inj_i & |err_inj_msk_i);\n        assign err_cor_o = {NDATA{1'b0}};\n        assign err_unc_o = {NDATA{1'b0}};\n    end\n\nendmodule\n// vim: ts=4 : sts=4 : sw=4 : et : tw=100 : spell : spelllang=en\n\n/*\n *  Copyright 2023 Commissariat a l'Energie Atomique et aux Energies Alternatives (CEA)\n *  Copyright 2025 Univ. Grenoble Alpes, Inria, TIMA Laboratory\n *\n *  SPDX-License-Identifier: Apache-2.0 WITH SHL-2.1\n */\n/*\n *  Authors       : Cesar Fuguet\n *  Creation Date : December, 2025\n *  Description   : Behavioral model of a 1RW SRAM with write bit mask and ECC\n *  History       :\n */\n`include \"prim_secded_inc.svh\"\n\nmodule hpdcache_sram_wmask_ecc_1rw\n#(\n    parameter int unsigned ADDR_SIZE = 0,\n    parameter int unsigned DATA_SIZE = 0,\n    parameter int unsigned DEPTH = 2**ADDR_SIZE,\n    parameter int unsigned NDATA = 1\n)\n(\n    input  logic                            clk,\n    input  logic                            rst_n,\n    input  logic                            cs,\n    input  logic                            we,\n    input  logic [ADDR_SIZE-1:0]            addr,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0] wdata,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0] wmask,\n    output logic [NDATA-1:0][DATA_SIZE-1:0] rdata,\n\n    input  logic                            err_inj_i,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0] err_inj_msk_i,\n    output logic [NDATA-1:0]                err_cor_o,\n    output logic [NDATA-1:0]                err_unc_o\n);\n\n    localparam int unsigned SYND_WIDTH = prim_secded_pkg::get_synd_width(\n        prim_secded_pkg::SecdedHsiao, DATA_SIZE);\n    localparam int unsigned WORD_WIDTH = prim_secded_pkg::get_full_width(\n        prim_secded_pkg::SecdedHsiao, DATA_SIZE);\n\n    logic [NDATA-1:0][WORD_WIDTH-1:0] wdata_ecc, rdata_ecc, wmask_ecc;\n    logic [NDATA-1:0][SYND_WIDTH-1:0] syndr_ecc;\n    logic [NDATA-1:0][1:0] err;\n\n    hpdcache_sram_wmask_1rw #(\n        .ADDR_SIZE (ADDR_SIZE),\n        .DATA_SIZE (WORD_WIDTH),\n        .DEPTH     (DEPTH),\n        .NDATA     (NDATA)\n    ) i_sram(\n        .clk,\n        .rst_n,\n        .cs,\n        .we,\n        .addr,\n        .wdata (wdata_ecc),\n        .wmask (wmask_ecc),\n        .rdata (rdata_ecc)\n    );\n\n    for (genvar i = 0; i < NDATA; i++) begin : gen_ecc_enc_dec\n        for (genvar j = 0; j < WORD_WIDTH; j++) begin : gen_ecc_wmask\n            if (j < DATA_SIZE) begin : gen_ecc_data_wmask\n                //  Data bits are written according to the write mask\n                assign wmask_ecc[i][j] = wmask[i][j];\n            end else begin : gen_ecc_check_wmask\n                //  Check bits byte are written if the last bit of the word is modified.\n                //  When using ECC, all the bits of word need to be written to correctly compute the\n                //  check bits. Hence, we can arbitrarily take a mask bit for the check bits\n                assign wmask_ecc[i][j] = wmask[i][DATA_SIZE-1];\n            end\n        end\n\n        `SECDED_INST_ENC(prim_secded_pkg::SecdedHsiao,\n            DATA_SIZE,\n            ecc_enc,\n            wdata[i],\n            wdata_ecc[i])\n\n        `SECDED_INST_DEC(prim_secded_pkg::SecdedHsiao,\n            DATA_SIZE,\n            ecc_dec,\n            rdata_ecc[i],\n            rdata[i],\n            syndr_ecc[i],\n            err[i])\n\n        assign err_cor_o[i] = err[i][0];\n        assign err_unc_o[i] = err[i][1];\n    end\n\n    //  Assertions\n    //  {{{\n`ifndef HPDCACHE_ASSERT_OFF\n    if (!prim_secded_pkg::is_width_valid(prim_secded_pkg::SecdedHsiao, DATA_SIZE))\n    begin : gen_ecc_valid_width_assertion\n        $fatal(1, $sformatf(\"Unsupported DATA_SIZE = %0d\", DATA_SIZE));\n    end\n`endif\n    //  }}}\n\nendmodule\n// vim: ts=4 : sts=4 : sw=4 : et : tw=100 : spell : spelllang=en\n\n/*\n *  Copyright 2023 Commissariat a l'Energie Atomique et aux Energies Alternatives (CEA)\n *  Copyright 2025 Univ. Grenoble Alpes, Inria, TIMA Laboratory\n *\n *  SPDX-License-Identifier: Apache-2.0 WITH SHL-2.1\n */\n/*\n *  Authors       : Cesar Fuguet\n *  Creation Date : March, 2020\n *  Description   : Behavioral model of a 1RW SRAM with write bit mask\n *  History       :\n */\nmodule hpdcache_sram_wmask_1rw\n#(\n    parameter int unsigned ADDR_SIZE = 0,\n    parameter int unsigned DATA_SIZE = 0,\n    parameter int unsigned DEPTH = 2**ADDR_SIZE,\n    parameter int unsigned NDATA = 1\n)\n(\n    input  logic                            clk,\n    input  logic                            rst_n,\n    input  logic                            cs,\n    input  logic                            we,\n    input  logic [ADDR_SIZE-1:0]            addr,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0] wdata,\n    input  logic [NDATA-1:0][DATA_SIZE-1:0] wmask,\n    output logic [NDATA-1:0][DATA_SIZE-1:0] rdata\n);\n\n    /*\n     *  Internal memory array declaration\n     */\n    typedef logic [NDATA-1:0][DATA_SIZE-1:0] mem_t [DEPTH];\n    mem_t mem;\n\n    /*\n     *  Process to update or read the memory array\n     */\n    always_ff @(posedge clk)\n    begin : mem_update_ff\n        if (cs == 1'b1) begin\n            if (we == 1'b1) begin\n                mem[addr] <= (mem[addr] & ~wmask) | (wdata & wmask);\n            end else begin\n                rdata <= mem[addr];\n            end\n        end\n    end : mem_update_ff\n\n    //  DPI\n    //  {{{\n`ifdef HPDCACHE_DPI_ON\n    export \"DPI-C\" task publicSramWmSetMask;\n    export \"DPI-C\" task publicSramWmSetData;\n\n    task automatic publicSramWmSetMask;\n        input int index;\n        input logic [NDATA-1:0][DATA_SIZE-1:0] mask;\n        mem[index] ^= mask;\n    endtask\n\n    task automatic publicSramWmSetData;\n        input int index;\n        input logic [NDATA-1:0][DATA_SIZE-1:0] data;\n        mem[index] = data;\n    endtask\n`endif\n    //  }}}\nendmodule\n// vim: ts=4 : sts=4 : sw=4 : et : tw=100 : spell : spelllang=en\n\n\n";
    let target = Target::from_token("synth").expect("target valid");
    let expected = Category::from_label("panic").expect("category valid");
    let r = oracle::evaluate(target, src, 20000);
    assert_ne!(
        r.category, expected,
        "regression: bug_1883_panic reproduced ({:?}): {}",
        r.category, r.detail.lines().next().unwrap_or("")
    );
}

#[test]
fn reg_bug_2028_lrm_violation() {
    let src = "// Seed 35: parallel-in/serial-out + clock divider\nmodule clock_div #(parameter DIV = 4) (\n  input  logic clk, rst_n,\n  output logic out\n);\n  logic [$clog2(DIV)-1:0] cnt;\n\n    if (!rst_n) begin\n      cnt <= '0;\n      out <= 1'b0;\n    end else begin\n      if (cnt == DIV-1) begin\n        cnt <= '0;\n        out <= ~out;\n      end else cnt <= cnt + 1;\n    end\n  end\nendmodule\n\nmodule piso #(parameter W = 8) (\n  input  logic clk, rst_n,\n  input  logic load,\n  input  logic [W-1:0] din,\n  output logic out\n);\n  logic [W-1:0] sh;\n  always_ff @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n      sh <= '0;\n      out <= 1'b0;\n    end else if (load) begin\n      sh <= din;\n    end else begin\n      out <= sh[W-1];\n      sh <= {sh[W-2:0], 1'b0};\n    end\n  end\nendmodule\n\n// Top: clock divider + PISO\nmodule top_clkdiv #(parameter DIV = 4, parameter W = 8) (\n  input  logic clk, rst_n,\n  input  logic load,\n  input  logic [W-1:0] din,\n  output logic div_out,\n  output logic s_out\n);\n  clock_div #(.DIV(DIV)) u_d (.clk(clk), .rst_n(rst_n), .out(div_out));\n  input  logic load,\n  input  logic [W-1:0] din,\n  output logic div_out,\n  output logic s_out\n);\n  clock_div #(.DIV(DIV)) u_d (.clk(clk), .rst_n(rst_n), .out(div_out));\n  piso #(.W(W)) u_p (.clk(clk), .rst_n(rst_n), .load(load), .din(din), .out(s_out));\nendmodule\n";
    let target = Target::from_token("judge").expect("target valid");
    let expected = Category::from_label("lrm_violation").expect("category valid");
    let r = oracle::evaluate(target, src, 20000);
    assert_ne!(
        r.category, expected,
        "regression: bug_2028_lrm_violation reproduced ({:?}): {}",
        r.category, r.detail.lines().next().unwrap_or("")
    );
}

